import { Module } from '@nestjs/common';
import { ConfigModule, ConfigService } from '@nestjs/config';
import { TypeOrmModule } from '@nestjs/typeorm';
import { AppController } from './app.controller';
import { AppService } from './app.service';
import { MonitoreoModule } from './monitoreo/monitoreo.module';
import { AuthModule } from './auth/auth.module';
import { GestionMaritimaModule } from './gestion_maritima/gestion_maritima.module';
import { GestionReservaModule } from './gestion_reserva/gestion_reserva.module';
import { GestionPortuariaModule } from './gestion_portuaria/gestion_portuaria.module';

@Module({
  imports: [
    // Configuración de variables de entorno
    ConfigModule.forRoot({
      isGlobal: true,
      envFilePath: '.env',
    }),

    // Configuración de TypeORM con PostgreSQL
    TypeOrmModule.forRootAsync({
      imports: [ConfigModule],
      inject: [ConfigService],
      useFactory: (configService: ConfigService) => {
        const databaseUrl = configService.get('DATABASE_URL');

        // Si existe DATABASE_URL (Producción con Supabase)
        if (databaseUrl) {
          return {
            type: 'postgres',
            url: databaseUrl,
            entities: [__dirname + '/**/*.entity{.ts,.js}'],
            synchronize: false,
            logging: process.env.NODE_ENV === 'development',
            ssl: {
              rejectUnauthorized: false, // Para Supabase
            },
          };
        }

        // Si no (Desarrollo local con pgAdmin)
        return {
          type: 'postgres',
          host: configService.get('DATABASE_HOST'),
          port: +configService.get('DATABASE_PORT'),
          username: configService.get('DATABASE_USER'),
          password: configService.get('DATABASE_PASSWORD'),
          database: configService.get('DATABASE_NAME'),
          entities: [__dirname + '/**/*.entity{.ts,.js}'],
          synchronize: false,
          logging: process.env.NODE_ENV === 'development',
        };
      },
    }),

    // Módulos de la aplicación
    AuthModule,
    MonitoreoModule,
    GestionMaritimaModule,
    GestionReservaModule,
    GestionPortuariaModule,
  ],
  controllers: [AppController],
  providers: [AppService],
})
export class AppModule { }

import { Controller, Post, Get, Body, Query, UseGuards, Request, Put, Param } from '@nestjs/common';
import { AuthService } from './auth.service';
import { LoginDto } from './dto/login.dto';
import { RegisterDto } from './dto/register.dto';
import { UpdateProfileDto } from './dto/update-profile.dto';
import { ChangePasswordDto } from './dto/change-password.dto';
import { JwtAuthGuard } from './guards/jwt-auth.guard';

@Controller('auth')
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  // POST /auth/login - Iniciar sesión
  @Post('login')
  async login(@Body() loginDto: LoginDto) {
    return await this.authService.login(loginDto);
  }

  // POST /auth/register - Registrar nuevo usuario
  @Post('register')
  async register(@Body() registerDto: RegisterDto) {
    return await this.authService.register(registerDto);
  }

  // GET /auth/roles - Obtener roles disponibles
  @Get('roles')
  async getRoles() {
    return await this.authService.getRoles();
  }

  // POST /auth/verify - Verificar token
  @Post('verify')
  async verifyToken(@Body('token') token: string) {
    return await this.authService.verifyToken(token);
  }

  // GET /auth/profile - Obtener perfil del usuario autenticado
  @Get('profile')
  @UseGuards(JwtAuthGuard)
  async getProfile(@Request() req) {
    return await this.authService.getProfile(req.user.id_usuario);
  }

  // PUT /auth/profile - Actualizar perfil del usuario autenticado
  @Put('profile')
  @UseGuards(JwtAuthGuard)
  async updateProfile(@Request() req, @Body() updateProfileDto: UpdateProfileDto) {
    return await this.authService.updateProfile(req.user.id_usuario, updateProfileDto);
  }

  // POST /auth/change-password - Cambiar contraseña
  @Post('change-password')
  @UseGuards(JwtAuthGuard)
  async changePassword(@Request() req, @Body() changePasswordDto: ChangePasswordDto) {
    return await this.authService.changePassword(req.user.id_usuario, changePasswordDto);
  }
}

import { Injectable, UnauthorizedException, ConflictException, NotFoundException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import * as bcrypt from 'bcrypt';
import { Usuario } from '../shared/entities/usuario.entity';
import { RolUsuario } from '../shared/entities/rol-usuario.entity';
import { Empleado } from '../shared/entities/empleado.entity';
import { Operador } from '../monitoreo/entities/operador.entity';
import { LoginDto } from './dto/login.dto';
import { RegisterDto } from './dto/register.dto';
import { UpdateProfileDto } from './dto/update-profile.dto';
import { ChangePasswordDto } from './dto/change-password.dto';

@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(Usuario)
    private usuarioRepository: Repository<Usuario>,
    @InjectRepository(RolUsuario)
    private rolUsuarioRepository: Repository<RolUsuario>,
    @InjectRepository(Empleado)
    private empleadoRepository: Repository<Empleado>,
    @InjectRepository(Operador)
    private operadorRepository: Repository<Operador>,
    private jwtService: JwtService,
  ) { }

  // Login unificado para todos los módulos
  // Las credenciales se validan en texto plano (desarrollo).
  // TODO: Para producción, usar bcrypt.
  async login(loginDto: LoginDto) {
    const { correo_electronico, contrasena } = loginDto;

    // Buscar usuario con sus relaciones
    const usuario = await this.usuarioRepository.findOne({
      where: { correo_electronico },
      relations: ['rol_usuario', 'empleado'],
    });

    if (!usuario) {
      throw new UnauthorizedException('Credenciales inválidas');
    }

    // Verificar contraseña (texto plano por ahora)
    if (contrasena !== usuario.contrasena) {
      throw new UnauthorizedException('Credenciales inválidas');
    }

    const rol = usuario.rol_usuario?.nombre;
    const operador = await this.operadorRepository.findOne({
      where: { id_empleado: usuario.id_empleado },
      relations: ['empleado'],
    });

    // Calcular módulos a los que el usuario tiene acceso
    const modulos: string[] = [];
    if (operador) {
      modulos.push('monitoreo');
    }
    if (rol && ['Administrador', 'Supervisor', 'Operador', 'Coordinador', 'Consultor', 'Auditor'].includes(rol)) {
      modulos.push('reservas');
    }
    if (rol && !['Agente de Reservas', 'Cliente', 'Trabajador Portuario'].includes(rol)) {
      modulos.push('maritimo');
    }
    if (rol && !['Agente de Reservas', 'Cliente'].includes(rol)) {
      modulos.push('portuario');
    }

    if (modulos.length === 0) {
      throw new UnauthorizedException('No tiene acceso a ningún módulo');
    }

    // Generar JWT
    const payload = {
      sub: usuario.id_usuario,
      correo: usuario.correo_electronico,
      id_empleado: usuario.id_empleado,
      rol,
      modulos,
    };

    const token = this.jwtService.sign(payload);

    return {
      access_token: token,
      usuario: {
        id_usuario: usuario.id_usuario,
        correo_electronico: usuario.correo_electronico,
        empleado: usuario.empleado ? {
          nombre: usuario.empleado.nombre,
          apellido: usuario.empleado.apellido,
          codigo: usuario.empleado.codigo,
        } : null,
        rol,
        operador: operador ? {
          id_operador: operador.id_operador,
          turno: operador.turno,
          zona_monitoreo: operador.zona_monitoreo,
        } : null,
      },
      modulos,
    };
  }

  // Registrar nuevo usuario (simplificado para operadores)
  async register(registerDto: RegisterDto) {
    const { correo_electronico, contrasena, id_rol_usuario, id_empleado } = registerDto;

    // Verificar si el usuario ya existe
    const usuarioExistente = await this.usuarioRepository.findOne({
      where: { correo_electronico },
    });

    if (usuarioExistente) {
      throw new ConflictException('El correo electrónico ya está registrado');
    }

    // Verificar que el rol existe
    const rol = await this.rolUsuarioRepository.findOne({
      where: { id_rol_usuario },
    });

    if (!rol) {
      throw new NotFoundException('Rol no encontrado');
    }

    // Hashear contraseña (desactivado temporalmente - guardar en texto plano)
    // TODO: Para producción, hashear con bcrypt
    const hashedPassword = contrasena; // Sin hashear
    // const hashedPassword = await bcrypt.hash(contrasena, 10); // Descomentar para producción

    // Crear usuario
    const nuevoUsuario = this.usuarioRepository.create({
      correo_electronico,
      contrasena: hashedPassword,
      id_rol_usuario,
      id_empleado,
    });

    await this.usuarioRepository.save(nuevoUsuario);

    return {
      message: 'Usuario registrado exitosamente',
      usuario: {
        id_usuario: nuevoUsuario.id_usuario,
        correo_electronico: nuevoUsuario.correo_electronico,
      },
    };
  }

  // Obtener roles disponibles
  async getRoles() {
    return await this.rolUsuarioRepository.find();
  }

  // Verificar token
  async verifyToken(token: string) {
    try {
      const payload = this.jwtService.verify(token);
      return payload;
    } catch (error) {
      throw new UnauthorizedException('Token inválido');
    }
  }

  // Actualizar perfil del usuario
  async updateProfile(id_usuario: string, updateProfileDto: UpdateProfileDto) {
    const usuario = await this.usuarioRepository.findOne({
      where: { id_usuario },
      relations: ['empleado'],
    });

    if (!usuario) {
      throw new NotFoundException('Usuario no encontrado');
    }

    // Actualizar datos del empleado
    if (updateProfileDto.nombre || updateProfileDto.apellido || updateProfileDto.direccion) {
      await this.empleadoRepository.update(usuario.id_empleado, {
        ...(updateProfileDto.nombre && { nombre: updateProfileDto.nombre }),
        ...(updateProfileDto.apellido && { apellido: updateProfileDto.apellido }),
        ...(updateProfileDto.direccion && { direccion: updateProfileDto.direccion }),
      });
    }

    // Obtener datos actualizados
    const empleadoActualizado = await this.empleadoRepository.findOne({
      where: { id_empleado: usuario.id_empleado },
    });

    if (!empleadoActualizado) {
      throw new NotFoundException('Empleado no encontrado');
    }

    return {
      message: 'Perfil actualizado exitosamente',
      empleado: {
        nombre: empleadoActualizado.nombre,
        apellido: empleadoActualizado.apellido,
        codigo: empleadoActualizado.codigo,
      },
    };
  }

  // Cambiar contraseña
  async changePassword(id_usuario: string, changePasswordDto: ChangePasswordDto) {
    const usuario = await this.usuarioRepository.findOne({
      where: { id_usuario },
    });

    if (!usuario) {
      throw new NotFoundException('Usuario no encontrado');
    }

    // Verificar contraseña actual (texto plano en desarrollo)
    // TODO: Para producción, usar bcrypt.compare
    const isPasswordValid = changePasswordDto.contrasenaActual === usuario.contrasena;
    // const isPasswordValid = await bcrypt.compare(changePasswordDto.contrasenaActual, usuario.contrasena);

    if (!isPasswordValid) {
      throw new UnauthorizedException('La contraseña actual es incorrecta');
    }

    // Actualizar contraseña (texto plano en desarrollo)
    // TODO: Para producción, hashear con bcrypt
    const nuevaContrasena = changePasswordDto.contrasenaNueva;
    // const nuevaContrasena = await bcrypt.hash(changePasswordDto.contrasenaNueva, 10);

    await this.usuarioRepository.update(id_usuario, {
      contrasena: nuevaContrasena,
    });

    return {
      message: 'Contraseña actualizada exitosamente',
    };
  }

  // Obtener perfil completo del usuario
  async getProfile(id_usuario: string) {
    const usuario = await this.usuarioRepository.findOne({
      where: { id_usuario },
      relations: ['rol_usuario', 'empleado'],
    });

    if (!usuario) {
      throw new NotFoundException('Usuario no encontrado');
    }

    if (!usuario.empleado) {
      throw new NotFoundException('El usuario no tiene un empleado asociado');
    }

    const operador = await this.operadorRepository.findOne({
      where: { id_empleado: usuario.id_empleado },
    });

    const rol = usuario.rol_usuario?.nombre;
    const modulos: string[] = [];
    if (operador) {
      modulos.push('monitoreo');
    }
    if (rol && ['Administrador', 'Supervisor', 'Operador', 'Coordinador', 'Consultor', 'Auditor'].includes(rol)) {
      modulos.push('reservas');
    }
    if (rol && !['Agente de Reservas', 'Cliente', 'Trabajador Portuario'].includes(rol)) {
      modulos.push('maritimo');
    }
    if (rol && !['Agente de Reservas', 'Cliente'].includes(rol)) {
      modulos.push('portuario');
    }

    return {
      id_usuario: usuario.id_usuario,
      correo_electronico: usuario.correo_electronico,
      rol,
      modulos,
      empleado: {
        id_empleado: usuario.empleado.id_empleado,
        nombre: usuario.empleado.nombre,
        apellido: usuario.empleado.apellido,
        codigo: usuario.empleado.codigo,
        dni: usuario.empleado.dni,
        direccion: usuario.empleado.direccion,
      },
      operador: operador ? {
        id_operador: operador.id_operador,
        turno: operador.turno,
        zona_monitoreo: operador.zona_monitoreo,
      } : null,
    };
  }
}

import { IsEmail, IsNotEmpty, IsString, IsUUID, MinLength } from 'class-validator';

export class RegisterDto {
  @IsEmail()
  @IsNotEmpty()
  correo_electronico: string;

  @IsString()
  @IsNotEmpty()
  @MinLength(6)
  contrasena: string;

  @IsUUID()
  @IsNotEmpty()
  id_rol_usuario: string;

  @IsUUID()
  @IsNotEmpty()
  id_empleado: string;
}

import { Injectable, ExecutionContext } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { Observable } from 'rxjs';

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  canActivate(context: ExecutionContext): boolean | Promise<boolean> | Observable<boolean> {
    return super.canActivate(context);
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Usuario } from '../../shared/entities/usuario.entity';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(
    @InjectRepository(Usuario)
    private usuarioRepository: Repository<Usuario>,
  ) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: process.env.JWT_SECRET || 'your-secret-key-change-in-production',
    });
  }

  async validate(payload: any) {
    const usuario = await this.usuarioRepository.findOne({
      where: { id_usuario: payload.sub },
      relations: ['empleado'],
    });

    if (!usuario) {
      throw new UnauthorizedException();
    }

    return {
      id_usuario: usuario.id_usuario,
      correo: usuario.correo_electronico,
      id_empleado: usuario.id_empleado,
    };
  }
}

import { IncidenciaRegistrada } from '../../monitoreo/dominio/incidencia-registrada.evento';

/** Efecto comprobable en el módulo de operaciones marítimas (Partición B). */
export interface AlertaOperativa {
  idIncidencia: string;
  codigoIncidencia: string;
  idOperacion: string;
  gradoSeveridad: number;
  registradaEn: Date;
}

/**
 * Consumidor de otro módulo: reacciona a IncidenciaRegistrada.
 * No lo conoce el caso de uso de monitoreo; se engancha al puerto de eventos.
 */
export class AlertaOperativaPorIncidenciaConsumer {
  private readonly alertas: AlertaOperativa[] = [];

  /** Solo las incidencias críticas (severidad 5) generan alerta operativa. */
  async manejar(evento: IncidenciaRegistrada): Promise<void> {
    if (evento.gradoSeveridad < 5) {
      return;
    }

    this.alertas.push({
      idIncidencia: evento.idIncidencia,
      codigoIncidencia: evento.codigo,
      idOperacion: evento.idOperacion,
      gradoSeveridad: evento.gradoSeveridad,
      registradaEn: evento.ocurrioEn,
    });
  }

  listarAlertas(): readonly AlertaOperativa[] {
    return this.alertas;
  }
}

