import { Controller, Get, Post, Body } from '@nestjs/common';
import { HallazgosService } from '../services/hallazgos.service';

@Controller('gestion-maritima/hallazgos')
export class HallazgosController {
  constructor(private readonly hallazgosService: HallazgosService) { }

  @Get('inspecciones')
  async getInspecciones() {
    const inspecciones = await this.hallazgosService.getInspecciones();

    // Map to frontend format
    return inspecciones.map(insp => ({
      id: insp.id_inspeccion,
      type: insp.tipoInspeccion?.nombre || 'N/A',
      date: insp.fecha.toISOString().split('T')[0],
      time: insp.fecha.toISOString().split('T')[1].substring(0, 5),
      priority: insp.prioridad?.nombre || 'N/A',
      operationCode: insp.operacion?.codigo || 'N/A',
      inspectionCode: insp.codigo,
      status: insp.estadoInspeccion?.nombre || 'N/A',
    }));
  }

  @Get('tipos')
  async getTiposHallazgo() {
    return this.hallazgosService.getTiposHallazgo();
  }

  @Post()
  async createHallazgo(
    @Body() body: {
      id_tipo_hallazgo: string;
      nivel_gravedad: number;
      descripcion: string;
      accion_sugerida?: string;
      id_inspeccion: string;
    }
  ) {
    // Generate codigo
    const codigo = `HAL-${Date.now()}`;

    return this.hallazgosService.createHallazgo({
      codigo,
      ...body
    });
  }
}

import { Controller, Post, Body, UseGuards, Request } from '@nestjs/common';
import { IncidenciasService } from '../services/incidencias.service';
import { CreateIncidenciaDto } from '../dto/create-incidencia.dto';
import { JwtAuthGuard } from '../../auth/guards/jwt-auth.guard';

@Controller('gestion-maritima/incidencias')
export class IncidenciasController {
    constructor(private readonly incidenciasService: IncidenciasService) { }

    @UseGuards(JwtAuthGuard)
    @Post()
    create(@Body() createIncidenciaDto: CreateIncidenciaDto, @Request() req) {
        return this.incidenciasService.create(createIncidenciaDto, req.user.id_usuario);
    }
}

import { Body, Controller, Get, Param, Patch, Post, Query } from '@nestjs/common';
import { OperacionMaritimaService } from '../services/operacion-maritima.service';
import { CreateOperacionMaritimaDto } from '../dto/create-operacion-maritima.dto';

@Controller('gestion-maritima/operaciones-maritimas')
export class OperacionMaritimaController {
    constructor(private readonly operacionMaritimaService: OperacionMaritimaService) { }

    @Post()
    create(@Body() createDto: CreateOperacionMaritimaDto) {
        return this.operacionMaritimaService.create(createDto);
    }

    @Get('estados')
    getEstados() {
        return this.operacionMaritimaService.getEstados();
    }

    @Get()
    findAll(@Query('page') page: string = '1', @Query('limit') limit: string = '10') {
        const pageNum = parseInt(page, 10) || 1;
        const limitNum = parseInt(limit, 10) || 10;
        return this.operacionMaritimaService.findAll(pageNum, limitNum);
    }

    @Get(':id')
    findOne(@Param('id') id: string) {
        return this.operacionMaritimaService.findOne(id);
    }

    @Patch(':id/estado')
    updateEstado(
        @Param('id') id: string,
        @Body() body: { id_estado_operacion?: string; estado_nombre?: string },
    ) {
        return this.operacionMaritimaService.updateEstado(id, body);
    }
}

import { Controller, Get, Post, Body, Query } from '@nestjs/common';
import { OperacionesIncidenciasService } from '../services/operaciones-incidencias.service';

@Controller('gestion-maritima/operaciones-incidencias')
export class OperacionesIncidenciasController {
    constructor(
        private readonly operacionesIncidenciasService: OperacionesIncidenciasService,
    ) { }

    @Get()
    async getOperacionesConIncidencias(
        @Query('page') page?: string,
        @Query('limit') limit?: string,
        @Query('search') search?: string,
        @Query('severidadMin') severidadMin?: string,
    ) {
        return this.operacionesIncidenciasService.getOperacionesConIncidencias(
            page ? parseInt(page) : 1,
            limit ? parseInt(limit) : 10,
            search,
            severidadMin ? parseInt(severidadMin) : undefined,
        );
    }

    @Post('marcar-investigacion')
    async marcarParaInvestigacion(
        @Body() body: {
            codigoOperacion: string;
            tipoInspeccion: string;
            prioridad: string;
            fecha: string;
            hora: string;
            idUsuario?: string;
        }
    ) {
        return this.operacionesIncidenciasService.marcarParaInvestigacion(
            body.codigoOperacion,
            body.tipoInspeccion,
            body.prioridad,
            body.fecha,
            body.hora,
            body.idUsuario,
        );
    }
}

import { Controller, Get, Param, Query } from '@nestjs/common';
