import { IsUUID, IsOptional, IsDateString, ValidateNested } from 'class-validator';
import { Type } from 'class-transformer';

export class CreateBuqueTripulanteDto {
  @IsUUID()
  id_buque: string;

  @IsUUID()
  id_tripulante: string;

  @IsOptional()
  @IsDateString()
  fecha_asignacion?: string;

  @IsOptional()
  hora_asignacion?: string;
}

import { IsNotEmpty, IsString, IsInt, IsUUID, Min, Max } from 'class-validator';

export class CreateIncidenciaDto {
    @IsNotEmpty()
    @IsString()
    codigo_operacion: string;

    @IsNotEmpty()
    @IsString()
    descripcion: string;

    @IsNotEmpty()
    @IsInt()
    @Min(1)
    @Max(5)
    grado_severidad: number;

    @IsNotEmpty()
    @IsUUID()
    id_tipo_incidencia: string;
}

import { IsString, IsNotEmpty, IsDateString, IsOptional, IsNumber, IsArray, IsUUID } from 'class-validator';

export class CreateOperacionMaritimaDto {
    @IsString()
    @IsNotEmpty()
    codigo: string;

    @IsDateString()
    @IsNotEmpty()
    fecha_inicio: string;

    @IsDateString()
    @IsOptional()
    fecha_fin?: string;

    @IsString()
    @IsNotEmpty()
    estado_nombre: string; // e.g., "En Planificación"

    @IsUUID()
    @IsNotEmpty()
    id_buque: string;

    @IsNumber()
    @IsOptional()
    cantidad_contenedores: number;

    @IsString()
    @IsOptional()
    estatus_navegacion_nombre?: string; // e.g., "En Puerto"

    @IsNumber()
    @IsOptional()
    porcentaje_trayecto: number;

    @IsUUID()
    @IsNotEmpty()
    id_ruta_maritima: string;

    @IsUUID()
    @IsNotEmpty()
    id_muelle_origen: string;

    @IsUUID()
    @IsNotEmpty()
    id_muelle_destino: string;

    @IsArray()
    @IsUUID('all', { each: true })
    tripulacion_ids: string[];

    @IsArray()
    @IsUUID('all', { each: true })
    contenedor_ids: string[];
}

