import { Injectable, NotFoundException, BadRequestException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { BuqueTripulante } from '../entities/buque-tripulante.entity';
import { CreateBuqueTripulanteDto } from '../dto/create-buque-tripulante.dto';
import { UpdateBuqueTripulanteDto } from '../dto/update-buque-tripulante.dto';
import { Buque } from '../../shared/entities/buque.entity';
import { Tripulante } from '../../shared/entities/tripulante.entity';

@Injectable()
export class BuqueTripulanteService {
  constructor(
    @InjectRepository(BuqueTripulante)
    private buqueTripulanteRepository: Repository<BuqueTripulante>,
    @InjectRepository(Buque)
    private buqueRepository: Repository<Buque>,
    @InjectRepository(Tripulante)
    private tripulanteRepository: Repository<Tripulante>,
  ) {}

  async create(createBuqueTripulanteDto: CreateBuqueTripulanteDto) {
    // Validar que el buque existe
    const buque = await this.buqueRepository.findOne({
      where: { id_buque: createBuqueTripulanteDto.id_buque },
    });
    if (!buque) {
      throw new NotFoundException('Buque no encontrado');
    }

    // Validar que el tripulante existe
    const tripulante = await this.tripulanteRepository.findOne({
      where: { id_tripulante: createBuqueTripulanteDto.id_tripulante },
    });
    if (!tripulante) {
      throw new NotFoundException('Tripulante no encontrado');
    }

    // Validar que el tripulante esté disponible
    if (!tripulante.disponibilidad) {
      throw new BadRequestException('Tripulante no está disponible');
    }

    // Verificar si ya existe una asignación activa
    const asignacionExistente = await this.buqueTripulanteRepository.findOne({
      where: {
        id_buque: createBuqueTripulanteDto.id_buque,
        id_tripulante: createBuqueTripulanteDto.id_tripulante,
      },
    });

    if (asignacionExistente) {
      throw new BadRequestException('El tripulante ya está asignado a este buque');
    }

    // Crear la asignación
    const buqueTripulante = this.buqueTripulanteRepository.create({
      ...createBuqueTripulanteDto,
      fecha_asignacion: createBuqueTripulanteDto.fecha_asignacion 
        ? new Date(createBuqueTripulanteDto.fecha_asignacion)
        : new Date(),
      hora_asignacion: createBuqueTripulanteDto.hora_asignacion
        ? new Date(`1970-01-01T${createBuqueTripulanteDto.hora_asignacion}`)
        : new Date(),
    });

    return await this.buqueTripulanteRepository.save(buqueTripulante);
  }

  async findAll() {
    return await this.buqueTripulanteRepository.find({
      relations: ['buque', 'tripulante', 'tripulante.empleado'],
    });
  }

  async findOne(id: string) {
    const buqueTripulante = await this.buqueTripulanteRepository.findOne({
      where: { id_buque_tripulante: id },
      relations: ['buque', 'tripulante', 'tripulante.empleado'],
    });

    if (!buqueTripulante) {
      throw new NotFoundException('Asignación no encontrada');
    }

    return buqueTripulante;
  }

  async findByBuque(id_buque: string) {
    return await this.buqueTripulanteRepository.find({
      where: { id_buque },
      relations: ['tripulante', 'tripulante.empleado'],
    });
  }

  async findByTripulante(id_tripulante: string) {
    return await this.buqueTripulanteRepository.find({
      where: { id_tripulante },
      relations: ['buque'],
    });
  }

  async update(id: string, updateBuqueTripulanteDto: UpdateBuqueTripulanteDto) {
    const buqueTripulante = await this.findOne(id);

    if (updateBuqueTripulanteDto.id_buque) {
      const buque = await this.buqueRepository.findOne({
        where: { id_buque: updateBuqueTripulanteDto.id_buque },
      });
      if (!buque) {
        throw new NotFoundException('Buque no encontrado');
      }
    }

    if (updateBuqueTripulanteDto.id_tripulante) {
      const tripulante = await this.tripulanteRepository.findOne({
        where: { id_tripulante: updateBuqueTripulanteDto.id_tripulante },
      });
      if (!tripulante) {
        throw new NotFoundException('Tripulante no encontrado');
      }
    }

    Object.assign(buqueTripulante, updateBuqueTripulanteDto);

    return await this.buqueTripulanteRepository.save(buqueTripulante);
  }

  async remove(id: string) {
    const buqueTripulante = await this.findOne(id);
    return await this.buqueTripulanteRepository.remove(buqueTripulante);
  }

  async removeByBuqueAndTripulante(id_buque: string, id_tripulante: string) {
    const asignacion = await this.buqueTripulanteRepository.findOne({
      where: { id_buque, id_tripulante },
    });

    if (!asignacion) {
      throw new NotFoundException('Asignación no encontrada');
    }

    return await this.buqueTripulanteRepository.remove(asignacion);
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Buque } from '../../shared/entities/buque.entity';

@Injectable()
export class BuquesService {
  constructor(
    @InjectRepository(Buque)
    private readonly buqueRepository: Repository<Buque>,
  ) { }

  async findBuques(
    page: number = 1,
    limit: number = 10,
    minWeight?: number,
    maxWeight?: number,
    stateId?: string,
  ) {
    try {
      const offset = (page - 1) * limit;
      let query = `
        SELECT 
            b.id_buque,
            b.matricula,
            b.nombre,
            b.capacidad,
            b.peso,
            b.ubicacion_actual,
            b.id_estado_embarcacion,
            ee.nombre AS estado
        FROM shared.Buque b
        JOIN shared.EstadoEmbarcacion ee ON b.id_estado_embarcacion = ee.id_estado_embarcacion
        WHERE 1=1
      `;

      const params: any[] = [];
      let paramIndex = 1;

      if (minWeight) {
        query += ` AND b.peso >= $${paramIndex++}`;
        params.push(minWeight);
      }
      if (maxWeight) {
        query += ` AND b.peso <= $${paramIndex++}`;
        params.push(maxWeight);
      }
      if (stateId) {
        query += ` AND b.id_estado_embarcacion = $${paramIndex++}`;
        params.push(stateId);
      }

      // Query para contar total
      const countQuery = `SELECT COUNT(*) as total FROM (${query}) as subquery`;

      // Query principal con paginación
      query += ` ORDER BY b.nombre LIMIT $${paramIndex++} OFFSET $${paramIndex++}`;
      params.push(limit, offset);

      const [data, countResult] = await Promise.all([
        this.buqueRepository.query(query, params),
        this.buqueRepository.query(countQuery, params.slice(0, -2))
      ]);

      const total = parseInt(countResult[0].total, 10);

      return {
        data: data.map((row: any) => ({
          id_buque: row.id_buque,
          matricula: row.matricula,
          nombre: row.nombre,
          capacidad: row.capacidad,
          peso: row.peso,
          ubicacion_actual: row.ubicacion_actual,
          id_estado_embarcacion: row.id_estado_embarcacion,
          estado_embarcacion: {
            id_estado_embarcacion: row.id_estado_embarcacion,
            nombre: row.estado
          }
        })),
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit)
      };
    } catch (error) {
      console.error('Error al obtener buques:', error);
      return {
        data: [],
        total: 0,
        page,
        limit,
        totalPages: 0
      };
    }
  }

  async findBuqueById(id: string) {
    try {
      return await this.buqueRepository.findOne({ where: { id_buque: id } });
    } catch (error) {
      console.error('Error al obtener buque por id:', error);
      return null;
    }
  }
}

import { Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';

@Injectable()
export class ConciliacionService {
  constructor(private readonly dataSource: DataSource) { }

  // Ejecutar proceso batch de conciliación nocturna
  async ejecutarConciliacionNocturna(fechaCorte?: string) {
    try {
      const fecha = fechaCorte ? new Date(fechaCorte) : new Date();
      const fechaStr = fecha.toISOString().split('T')[0];

      await this.dataSource.query(
        'SELECT gestion_maritima_audit.f_conciliacion_nocturna_operaciones($1)',
        [fechaStr],
      );

      return {
        message: 'Proceso de conciliación nocturna ejecutado correctamente',
        fecha_corte: fechaStr,
      };
    } catch (error: any) {
      console.error('Error al ejecutar conciliación nocturna:', error.message || error);
      throw new Error('Error al ejecutar el proceso de conciliación nocturna');
    }
  }

  // Obtener correcciones aplicadas
  async getCorrecciones(fechaDesde?: string, fechaHasta?: string) {
    try {
      const hoy = new Date();
      const desde = fechaDesde ? new Date(fechaDesde) : new Date(hoy.setDate(hoy.getDate() - 30));
      const hasta = fechaHasta ? new Date(fechaHasta) : new Date();

      // Total de correcciones aplicadas
      const totalCorrecciones = await this.dataSource.query(
        `
        SELECT COUNT(*) as total
        FROM gestion_maritima_audit.FactConciliacionOperacion fco
        JOIN gestion_maritima_audit.DimFecha df ON df.id_fecha = fco.id_fecha_corte
        WHERE df.fecha BETWEEN $1 AND $2
          AND fco.correccion_aplicada = true
        `,
        [desde.toISOString().split('T')[0], hasta.toISOString().split('T')[0]],
      );

      // Correcciones por tipo
      const correccionesPorTipo = await this.dataSource.query(
        `
        SELECT 
          fco.tipo_correccion,
          COUNT(*) as cantidad
        FROM gestion_maritima_audit.FactConciliacionOperacion fco
        JOIN gestion_maritima_audit.DimFecha df ON df.id_fecha = fco.id_fecha_corte
        WHERE df.fecha BETWEEN $1 AND $2
          AND fco.correccion_aplicada = true
        GROUP BY fco.tipo_correccion
        ORDER BY cantidad DESC
        `,
        [desde.toISOString().split('T')[0], hasta.toISOString().split('T')[0]],
      );

      // Lista de operaciones corregidas
      const operacionesCorregidas = await this.dataSource.query(
        `
        SELECT 
          fco.id_operacion,
          o.codigo as codigo_operacion,
          fco.tipo_correccion,
          fco.descripcion_correccion,
          df.fecha as fecha_corte,
          deo_ant.nombre as estado_anterior,
          deo_new.nombre as estado_nuevo,
          fco.duracion_real_horas,
          fco.incidencias_asociadas,
          fco.incidencias_alta_severidad,
          fco.requiere_intervencion_manual
        FROM gestion_maritima_audit.FactConciliacionOperacion fco
        JOIN gestion_maritima_audit.DimFecha df ON df.id_fecha = fco.id_fecha_corte
        JOIN shared.Operacion o ON o.id_operacion = fco.id_operacion
        JOIN gestion_maritima_audit.DimEstadoOperacion deo_ant 
          ON deo_ant.id_estado_operacion = fco.id_estado_operacion_anterior
        JOIN gestion_maritima_audit.DimEstadoOperacion deo_new 
          ON deo_new.id_estado_operacion = fco.id_estado_operacion_nuevo
        WHERE df.fecha BETWEEN $1 AND $2
          AND fco.correccion_aplicada = true
        ORDER BY df.fecha DESC, fco.fecha_registro_batch DESC
        LIMIT 50
        `,
        [desde.toISOString().split('T')[0], hasta.toISOString().split('T')[0]],
      );

      return {
        total_correcciones: parseInt(totalCorrecciones[0]?.total || '0'),
        correcciones_por_tipo: correccionesPorTipo,
        operaciones_corregidas: operacionesCorregidas,
        fecha_desde: desde.toISOString().split('T')[0],
        fecha_hasta: hasta.toISOString().split('T')[0],
      };
    } catch (error: any) {
      console.error('Error al obtener correcciones:', error.message || error);
      throw new Error('Error al obtener las correcciones aplicadas');
    }
  }

  // Obtener métricas para el dashboard
  async getDashboardMetricas() {
    try {
      // KPIs principales
      const kpis = await this.dataSource.query(`
        SELECT
          COUNT(DISTINCT o.id_operacion) as total_operaciones,
          COUNT(DISTINCT CASE WHEN eo.nombre = 'En Curso' THEN o.id_operacion END) as operaciones_activas,
          COUNT(DISTINCT CASE WHEN eo.nombre = 'Completada' THEN o.id_operacion END) as operaciones_finalizadas,
          COUNT(DISTINCT i.id_incidencia) as total_incidencias,
          COUNT(DISTINCT CASE WHEN i.grado_severidad >= 4 THEN i.id_incidencia END) as incidencias_criticas
        FROM shared.Operacion o
        LEFT JOIN shared.EstadoOperacion eo ON eo.id_estado_operacion = o.id_estado_operacion
        LEFT JOIN shared.Incidencia i ON i.id_operacion = o.id_operacion
        WHERE o.fecha_inicio >= CURRENT_DATE - INTERVAL '30 days'
      `);

      // Correcciones recientes (últimos 7 días)
      const correccionesRecientes = await this.dataSource.query(`
        SELECT COUNT(*) as total
        FROM gestion_maritima_audit.FactConciliacionOperacion fco
        JOIN gestion_maritima_audit.DimFecha df ON df.id_fecha = fco.id_fecha_corte
        WHERE df.fecha >= CURRENT_DATE - INTERVAL '7 days'
          AND fco.correccion_aplicada = true
      `);

      // Operaciones que requieren intervención manual
      const intervencionManual = await this.dataSource.query(`
        SELECT COUNT(*) as total
        FROM gestion_maritima_audit.FactConciliacionOperacion
        WHERE requiere_intervencion_manual = true
          AND fecha_registro_batch >= CURRENT_DATE - INTERVAL '7 days'
      `);

      // Tendencia de correcciones por día (últimos 7 días)
      const tendenciaCorrecciones = await this.dataSource.query(`
        SELECT 
          df.fecha,
          COUNT(*) as cantidad_correcciones
        FROM gestion_maritima_audit.FactConciliacionOperacion fco
        JOIN gestion_maritima_audit.DimFecha df ON df.id_fecha = fco.id_fecha_corte
        WHERE df.fecha >= CURRENT_DATE - INTERVAL '7 days'
          AND fco.correccion_aplicada = true
        GROUP BY df.fecha
        ORDER BY df.fecha ASC
      `);

      // Distribución por tipo de corrección
      const distribucionCorrecciones = await this.dataSource.query(`
        SELECT 
          tipo_correccion,
          COUNT(*) as cantidad
        FROM gestion_maritima_audit.FactConciliacionOperacion
        WHERE fecha_registro_batch >= CURRENT_DATE - INTERVAL '30 days'
          AND correccion_aplicada = true
        GROUP BY tipo_correccion
        ORDER BY cantidad DESC
      `);

      return {
        kpis: {
          total_operaciones: parseInt(kpis[0]?.total_operaciones || '0'),
          operaciones_activas: parseInt(kpis[0]?.operaciones_activas || '0'),
          operaciones_finalizadas: parseInt(kpis[0]?.operaciones_finalizadas || '0'),
          total_incidencias: parseInt(kpis[0]?.total_incidencias || '0'),
          incidencias_criticas: parseInt(kpis[0]?.incidencias_criticas || '0'),
          correcciones_recientes: parseInt(correccionesRecientes[0]?.total || '0'),
          intervencion_manual: parseInt(intervencionManual[0]?.total || '0'),
        },
        tendencia_correcciones: tendenciaCorrecciones,
        distribucion_correcciones: distribucionCorrecciones,
      };
    } catch (error: any) {
      console.error('Error al obtener métricas del dashboard:', error.message || error);
      return {
        kpis: {
          total_operaciones: 0,
          operaciones_activas: 0,
          operaciones_finalizadas: 0,
          total_incidencias: 0,
          incidencias_criticas: 0,
          correcciones_recientes: 0,
          intervencion_manual: 0,
        },
        tendencia_correcciones: [],
        distribucion_correcciones: [],
      };
    }
  }

  // Obtener todas las operaciones marítimas con indicador de corrección
  async getTodasOperaciones() {
    try {
      const operaciones = await this.dataSource.query(`
                SELECT 
                    om.id_operacion,
                    o.codigo as codigo_operacion,
                    o.fecha_inicio,
                    o.fecha_fin,
                    eo.nombre as estado,
                    b.nombre as buque,
                    b.matricula,
                    om.porcentaje_trayecto,
                    COUNT(DISTINCT i.id_incidencia) as total_incidencias,
                    COUNT(DISTINCT CASE WHEN i.grado_severidad >= 4 THEN i.id_incidencia END) as incidencias_criticas,
                    CASE 
                        WHEN fco.id_operacion IS NOT NULL THEN true 
                        ELSE false 
                    END as fue_corregida,
                    fco.tipo_correccion,
                    fco.descripcion_correccion,
                    fco.fecha_registro_batch as fecha_correccion
                FROM shared.OperacionMaritima om
                JOIN shared.Operacion o ON o.id_operacion = om.id_operacion
                LEFT JOIN shared.EstadoOperacion eo ON eo.id_estado_operacion = o.id_estado_operacion
                LEFT JOIN shared.Buque b ON b.id_buque = om.id_buque
                LEFT JOIN shared.Incidencia i ON i.id_operacion = o.id_operacion
                LEFT JOIN (
                    SELECT DISTINCT ON (id_operacion) 
                        id_operacion, 
                        tipo_correccion, 
                        descripcion_correccion,
                        fecha_registro_batch
                    FROM gestion_maritima_audit.FactConciliacionOperacion
                    WHERE correccion_aplicada = true
                    ORDER BY id_operacion, fecha_registro_batch DESC
                ) fco ON fco.id_operacion = om.id_operacion
                WHERE o.fecha_inicio >= CURRENT_DATE - INTERVAL '30 days'
                GROUP BY 
                    om.id_operacion, o.codigo, o.fecha_inicio, o.fecha_fin,
                    eo.nombre, b.nombre, b.matricula, om.porcentaje_trayecto,
                    fco.id_operacion, fco.tipo_correccion, fco.descripcion_correccion,
                    fco.fecha_registro_batch
                ORDER BY o.fecha_inicio DESC
            `);

      return operaciones.map((op: any) => ({
        id_operacion: op.id_operacion,
        codigo_operacion: op.codigo_operacion,
        fecha_inicio: op.fecha_inicio,
        fecha_fin: op.fecha_fin,
        estado: op.estado || 'N/A',
        buque: op.buque || 'N/A',
        matricula: op.matricula || 'N/A',
        porcentaje_trayecto: parseFloat(op.porcentaje_trayecto || '0'),
        total_incidencias: parseInt(op.total_incidencias || '0'),
        incidencias_criticas: parseInt(op.incidencias_criticas || '0'),
        fue_corregida: op.fue_corregida,
        tipo_correccion: op.tipo_correccion,
        descripcion_correccion: op.descripcion_correccion,
        fecha_correccion: op.fecha_correccion,
      }));
    } catch (error: any) {
      console.error('Error al obtener operaciones:', error.message || error);
      return [];
    }
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { Contenedor } from '../../shared/entities/contenedor.entity';
import { EstadoContenedor } from '../../shared/entities/estado-contenedor.entity';
import { TipoContenedor } from '../../shared/entities/tipo-contenedor.entity';
import { ReservaContenedor } from '../../gestion_reserva/entities/reserva-contenedor.entity';
import { Reserva } from '../../gestion_reserva/entities/reserva.entity';
import { Cliente } from '../../gestion_reserva/entities/cliente.entity';
import { ContenedorMercancia } from '../../shared/entities/contenedor-mercancia.entity';

@Injectable()
export class ContenedoresMaritimosService {
  constructor(
    @InjectRepository(Contenedor)
    private readonly contenedorRepository: Repository<Contenedor>,
    @InjectRepository(EstadoContenedor)
    private readonly estadoContenedorRepository: Repository<EstadoContenedor>,
    @InjectRepository(TipoContenedor)
    private readonly tipoContenedorRepository: Repository<TipoContenedor>,
    @InjectRepository(ReservaContenedor)
    private readonly reservaContenedorRepository: Repository<ReservaContenedor>,
    @InjectRepository(Reserva)
    private readonly reservaRepository: Repository<Reserva>,
    @InjectRepository(Cliente)
    private readonly clienteRepository: Repository<Cliente>,
    @InjectRepository(ContenedorMercancia)
    private readonly contenedorMercanciaRepository: Repository<ContenedorMercancia>,
  ) { }

  async findContenedores(
    page: number = 1,
    limit: number = 10,
    estado?: string,
    mercancia?: string,
  ) {
    try {
      const offset = (page - 1) * limit;

      let query = `
        SELECT   
            c.id_contenedor,
            c.codigo,
            tc.nombre AS tipo_nombre,    
            c.capacidad,
            c.dimensiones,
            ec.nombre AS estado,      
            cm.tipo_mercancia
        FROM shared.Contenedor c
        JOIN shared.EstadoContenedor ec ON c.id_estado_contenedor = ec.id_estado_contenedor
        JOIN shared.TipoContenedor tc ON c.id_tipo_contenedor = tc.id_tipo_contenedor
        LEFT JOIN shared.ContenedorMercancia cm ON c.id_contenedor = cm.id_contenedor
        WHERE 1=1
      `;

      const params: any[] = [];
      let paramIndex = 1;

      if (estado) {
        query += ` AND ec.nombre = $${paramIndex++}`;
        params.push(estado);
      }
      if (mercancia) {
        query += ` AND cm.tipo_mercancia ILIKE $${paramIndex++}`;
        params.push(`%${mercancia}%`);
      }

      const countQuery = `SELECT COUNT(DISTINCT subquery.id_contenedor) as total FROM (${query}) as subquery`;

      query += ` ORDER BY c.codigo LIMIT $${paramIndex++} OFFSET $${paramIndex++}`;
      params.push(limit, offset);

      const [data, countResult] = await Promise.all([
        this.contenedorRepository.query(query, params),
        this.contenedorRepository.query(countQuery, params.slice(0, -2))
      ]);

      const total = parseInt(countResult[0].total, 10);

      return {
        data: data.map((row: any) => ({
          id_contenedor: row.id_contenedor,
          codigo: row.codigo,
          tipo_contenedor: {
            nombre: row.tipo_nombre
          },
          capacidad: row.capacidad,
          dimensiones: row.dimensiones,
          estado_contenedor: {
            nombre: row.estado
          },
          mercancia: row.tipo_mercancia,
          cliente: null // Not included in the SQL query
        })),
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit)
      };
    } catch (error) {
      console.error('Error al obtener contenedores marítimos:', error);
      return {
        data: [],
        total: 0,
        page,
        limit,
        totalPages: 0
      };
    }
  }
}

