import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AgenteReservas } from '../entities/agente-reservas.entity';

@Injectable()
export class AgentesService {
  constructor(
    @InjectRepository(AgenteReservas)
    private readonly agenteRepository: Repository<AgenteReservas>,
  ) {}

  async findAll(): Promise<any[]> {
    const query = `
      SELECT 
        ar.id_agente_reservas,
        ar.id_empleado,
        e.nombre AS empleado_nombre,
        e.apellido AS empleado_apellido,
        e.codigo AS empleado_codigo
      FROM gestion_reserva.agentereservas ar
      JOIN shared.empleado e ON ar.id_empleado = e.id_empleado
      ORDER BY e.apellido ASC, e.nombre ASC
    `;

    const result = await this.agenteRepository.query(query);

    return result.map((row: any) => ({
      id_agente_reservas: row.id_agente_reservas,
      id_empleado: row.id_empleado,
      empleado: {
        id_empleado: row.id_empleado,
        nombre: row.empleado_nombre,
        apellido: row.empleado_apellido,
        codigo: row.empleado_codigo,
      },
    }));
  }

  async findOne(id: string): Promise<any> {
    const query = `
      SELECT 
        ar.id_agente_reservas,
        ar.id_empleado,
        e.nombre AS empleado_nombre,
        e.apellido AS empleado_apellido,
        e.codigo AS empleado_codigo
      FROM gestion_reserva.agentereservas ar
      JOIN shared.empleado e ON ar.id_empleado = e.id_empleado
      WHERE ar.id_agente_reservas = $1
    `;

    const result = await this.agenteRepository.query(query, [id]);

    if (result.length === 0) {
      throw new NotFoundException(`Agente con ID ${id} no encontrado`);
    }

    const row = result[0];

    // Obtener reservas del agente
    const reservasQuery = `
      SELECT 
        r.id_reserva,
        r.codigo,
        r.fecha_registro,
        c.razon_social AS cliente,
        er.nombre AS estado
      FROM gestion_reserva.reserva r
      LEFT JOIN gestion_reserva.cliente c ON r.ruc_cliente = c.ruc
      LEFT JOIN shared.estadoreserva er ON r.id_estado_reserva = er.id_estado_reserva
      WHERE r.id_agente_reservas = $1
      ORDER BY r.fecha_registro DESC
    `;
    const reservas = await this.agenteRepository.query(reservasQuery, [id]);

    return {
      id_agente_reservas: row.id_agente_reservas,
      id_empleado: row.id_empleado,
      empleado: {
        id_empleado: row.id_empleado,
        nombre: row.empleado_nombre,
        apellido: row.empleado_apellido,
        codigo: row.empleado_codigo,
      },
      reservas: reservas,
    };
  }

  async findByEmpleado(idEmpleado: string): Promise<any> {
    const query = `
      SELECT 
        ar.id_agente_reservas,
        ar.id_empleado,
        e.nombre AS empleado_nombre,
        e.apellido AS empleado_apellido,
        e.codigo AS empleado_codigo
      FROM gestion_reserva.agentereservas ar
      JOIN shared.empleado e ON ar.id_empleado = e.id_empleado
      WHERE ar.id_empleado = $1
    `;

    const result = await this.agenteRepository.query(query, [idEmpleado]);

    if (result.length === 0) {
      throw new NotFoundException(`Agente con empleado ID ${idEmpleado} no encontrado`);
    }

    const row = result[0];

    return {
      id_agente_reservas: row.id_agente_reservas,
      id_empleado: row.id_empleado,
      empleado: {
        id_empleado: row.id_empleado,
        nombre: row.empleado_nombre,
        apellido: row.empleado_apellido,
        codigo: row.empleado_codigo,
      },
    };
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Buque } from '../../shared/entities/buque.entity';
import { OperacionMaritima } from '../../shared/entities/operacion-maritima.entity';

@Injectable()
export class BuquesOperacionesService {
  constructor(
    @InjectRepository(Buque)
    private readonly buqueRepository: Repository<Buque>,
    @InjectRepository(OperacionMaritima)
    private readonly operacionMaritimaRepository: Repository<OperacionMaritima>,
  ) {}

  async findBuquesConOperaciones(): Promise<any[]> {
    try {
      const query = `
        SELECT * FROM (
          SELECT DISTINCT ON (b.id_buque)
            b.id_buque,
            b.nombre,
            b.matricula,
            b.capacidad,
            om.porcentaje_trayecto,
            eo.nombre AS estado_operacion
          FROM shared.buque b
          JOIN shared.operacionmaritima om ON b.id_buque = om.id_buque
          JOIN shared.operacion o ON om.id_operacion = o.id_operacion
          JOIN shared.estadooperacion eo ON o.id_estado_operacion = eo.id_estado_operacion
          WHERE eo.nombre IN ('En Curso', 'Programada')
          ORDER BY b.id_buque, om.porcentaje_trayecto DESC
        ) AS buques
        ORDER BY porcentaje_trayecto DESC
      `;

      const result = await this.buqueRepository.query(query);

      return result.map((row: any) => ({
        id_buque: row.id_buque,
        nombre: row.nombre,
        matricula: row.matricula,
        capacidad: row.capacidad,
        porcentaje_trayecto: Number(row.porcentaje_trayecto) || 0,
        estado_operacion: row.estado_operacion,
      }));
    } catch (error) {
      console.error('Error al obtener buques con operaciones:', error);
      return [];
    }
  }
}

