import { Injectable, NotFoundException, BadRequestException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Entrega } from '../entities/entrega.entity';
import { EstadoEntrega } from '../../shared/entities/estado-entrega.entity';
import { Contenedor } from '../../shared/entities/contenedor.entity';
import { Importador } from '../entities/importador.entity';

export interface CreateEntregaDto {
  id_contenedor: string;
  id_importador: string;
  fecha_entrega: Date;
  lugar_entrega: string;
}

export interface UpdateEntregaDto {
  id_estado_entrega?: string;
  fecha_entrega?: Date;
  lugar_entrega?: string;
}

@Injectable()
export class EntregasService {
  constructor(
    @InjectRepository(Entrega)
    private entregaRepository: Repository<Entrega>,
    @InjectRepository(EstadoEntrega)
    private estadoEntregaRepository: Repository<EstadoEntrega>,
    @InjectRepository(Contenedor)
    private contenedorRepository: Repository<Contenedor>,
    @InjectRepository(Importador)
    private importadorRepository: Repository<Importador>,
  ) {}

  // Listar todas las entregas con paginación y filtros
  async findAll(filtros: any = {}) {
    try {
      const { limite = 20, pagina = 1, estado, desde, hasta } = filtros;

      const query = this.entregaRepository
        .createQueryBuilder('entrega')
        .leftJoinAndSelect('entrega.estado_entrega', 'estado_entrega')
        .leftJoinAndSelect('entrega.contenedor', 'contenedor')
        .leftJoinAndSelect('entrega.importador', 'importador')
        .orderBy('entrega.fecha_entrega', 'DESC');

      // Filtros
      if (estado) {
        query.andWhere('entrega.id_estado_entrega = :estado', { estado });
      }
      if (desde) {
        query.andWhere('entrega.fecha_entrega >= :desde', { desde });
      }
      if (hasta) {
        query.andWhere('entrega.fecha_entrega <= :hasta', { hasta });
      }

      const skip = (pagina - 1) * limite;
      query.skip(skip).take(limite);

      const [entregas, total] = await query.getManyAndCount();

      return {
        entregas,
        total,
        pagina: Number(pagina),
        total_paginas: Math.ceil(total / limite),
        por_pagina: Number(limite),
      };
    } catch (error) {
      console.error('Error en findAll entregas:', error.message);
      return {
        entregas: [],
        total: 0,
        pagina: 1,
        total_paginas: 0,
        por_pagina: 20,
      };
    }
  }

  // Obtener una entrega por ID
  async findOne(id: string) {
    try {
      const entrega = await this.entregaRepository.findOne({
        where: { id_entrega: id },
        relations: ['estado_entrega', 'contenedor', 'contenedor.tipo_contenedor', 'importador'],
      });

      if (!entrega) {
        throw new NotFoundException(`Entrega con ID ${id} no encontrada`);
      }

      return entrega;
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      console.error('Error en findOne entrega:', error.message);
      throw new Error('Error al obtener la entrega');
    }
  }

  // Crear nueva entrega
  async create(data: CreateEntregaDto) {
    try {
      // Generar código único
      const codigo = await this.generarCodigo();

      // Obtener estado inicial (Pendiente)
      const estadoInicial = await this.estadoEntregaRepository.findOne({
        where: { nombre: 'Pendiente' },
      });

      if (!estadoInicial) {
        throw new Error('Estado inicial "Pendiente" no encontrado');
      }

      const entrega = this.entregaRepository.create({
        codigo,
        id_estado_entrega: estadoInicial.id_estado_entrega,
        id_contenedor: data.id_contenedor,
        id_importador: data.id_importador,
        fecha_entrega: data.fecha_entrega || new Date(),
        lugar_entrega: data.lugar_entrega,
      });

      return await this.entregaRepository.save(entrega);
    } catch (error) {
      console.error('Error en create entrega:', error.message);
      throw new Error('Error al crear la entrega');
    }
  }

  // Actualizar entrega
  async update(id: string, data: UpdateEntregaDto) {
    try {
      const entrega = await this.findOne(id);

      if (data.id_estado_entrega !== undefined) {
        entrega.id_estado_entrega = data.id_estado_entrega;
      }
      if (data.fecha_entrega !== undefined) {
        entrega.fecha_entrega = data.fecha_entrega;
      }
      if (data.lugar_entrega !== undefined) {
        entrega.lugar_entrega = data.lugar_entrega;
      }

      return await this.entregaRepository.save(entrega);
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      console.error('Error en update entrega:', error.message);
      throw new Error('Error al actualizar la entrega');
    }
  }

  // Finalizar entrega (marcar como Entregada)
  async finalize(id: string) {
    try {
      const entrega = await this.entregaRepository.findOne({
        where: { id_entrega: id },
        relations: ['estado_entrega'],
      });

      if (!entrega) {
        throw new NotFoundException(`Entrega con ID ${id} no encontrada`);
      }

      const estadoActual = entrega.estado_entrega?.nombre?.toLowerCase() || '';

      // Solo permitir finalizar si no está ya entregada/cancelada
      const noFinalizable = ['entregada', 'cancelada'];
      if (noFinalizable.includes(estadoActual)) {
        throw new BadRequestException(
          'Solo se pueden finalizar entregas que no estén ya "Entregada" o "Cancelada".',
        );
      }

      // Buscar estado "Entregada"
      const estadoEntregada = await this.estadoEntregaRepository.findOne({
        where: { nombre: 'Entregada' },
      });

      if (!estadoEntregada) {
        throw new Error('Estado "Entregada" no encontrado en la tabla estadoentrega');
      }

      await this.entregaRepository.update(
        { id_entrega: id },
        { id_estado_entrega: estadoEntregada.id_estado_entrega },
      );

      // Devolver entrega actualizada con relaciones
      const entregaActualizada = await this.entregaRepository.findOne({
        where: { id_entrega: id },
        relations: ['estado_entrega', 'contenedor', 'contenedor.tipo_contenedor', 'importador'],
      });

      return entregaActualizada;
    } catch (error) {
      if (error instanceof NotFoundException || error instanceof BadRequestException) {
        throw error;
      }
      console.error('Error en finalize entrega:', error.message);
      throw new Error('Error al finalizar la entrega');
    }
  }

  // Eliminar entrega
  async remove(id: string) {
    try {
      const entrega = await this.findOne(id);
      await this.entregaRepository.remove(entrega);
      return { message: 'Entrega eliminada correctamente' };
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      console.error('Error en remove entrega:', error.message);
      throw new Error('Error al eliminar la entrega');
    }
  }

  // Obtener estados de entrega
  async getEstadosEntrega() {
    try {
      const estados = await this.estadoEntregaRepository.find();
      console.log('Estados de entrega encontrados:', estados.length);
      return estados;
    } catch (error) {
      console.error('Error al obtener estados de entrega:', error.message);
      return [];
    }
  }

  // Obtener estadísticas
  async getEstadisticas() {
    try {
      // Total de entregas usando SQL explícito
      const totalRows = await this.entregaRepository.query(
        `
        SELECT COUNT(*)::int AS total
        FROM monitoreo.entrega
        `,
      );

      const total =
        totalRows && totalRows.length > 0
          ? Number(totalRows[0].total) || 0
          : 0;

      const hoy = new Date();
      const inicioMes = new Date(hoy.getFullYear(), hoy.getMonth(), 1);
      const finMes = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);

      // Entregas de este mes usando SQL explícito
      const esteMesRows = await this.entregaRepository.query(
        `
        SELECT COUNT(*)::int AS total
        FROM monitoreo.entrega
        WHERE fecha_entrega >= $1
          AND fecha_entrega <= $2
        `,
        [inicioMes, finMes],
      );

      const esteMes =
        esteMesRows && esteMesRows.length > 0
          ? Number(esteMesRows[0].total) || 0
          : 0;

      // Entregas pendientes (estado "Pendiente") usando SQL explícito
      const pendientesRows = await this.entregaRepository.query(
        `
        SELECT COUNT(*)::int AS total
        FROM monitoreo.entrega e
        JOIN shared.estadoentrega ee 
          ON ee.id_estado_entrega = e.id_estado_entrega
        WHERE ee.nombre = $1
        `,
        ['Pendiente'],
      );

      const pendientes =
        pendientesRows && pendientesRows.length > 0
          ? Number(pendientesRows[0].total) || 0
          : 0;

      return {
        total,
        este_mes: esteMes,
        pendientes,
      };
    } catch (error) {
      console.error('Error en getEstadisticas entregas:', error.message);
      return {
        total: 0,
        este_mes: 0,
        pendientes: 0,
      };
    }
  }

  // Obtener contenedores disponibles
  async getContenedoresDisponibles() {
    try {
      // Obtener contenedores que no tienen entrega asignada
      const contenedores = await this.contenedorRepository
        .createQueryBuilder('contenedor')
        .leftJoinAndSelect('contenedor.tipo_contenedor', 'tipo')
        .leftJoin(Entrega, 'entrega', 'entrega.id_contenedor = contenedor.id_contenedor')
        .where('entrega.id_entrega IS NULL')
        .take(100)
        .getMany();

      return contenedores;
    } catch (error) {
      console.error('Error al obtener contenedores disponibles:', error.message);
      return [];
    }
  }

  // Obtener importadores
  async getImportadores() {
    try {
      const importadores = await this.importadorRepository.find({
        take: 100,
      });
      return importadores;
    } catch (error) {
      console.error('Error al obtener importadores:', error.message);
      return [];
    }
  }

  // Generar código único para la entrega
  private async generarCodigo(): Promise<string> {
    const fecha = new Date();
    const año = fecha.getFullYear().toString().slice(-2);
    const mes = (fecha.getMonth() + 1).toString().padStart(2, '0');

    // Obtener el último código del mes
    const ultimaEntrega = await this.entregaRepository
      .createQueryBuilder('entrega')
      .where('entrega.codigo LIKE :patron', { patron: `ENT-${año}${mes}-%` })
      .orderBy('entrega.codigo', 'DESC')
      .limit(1)
      .getOne();

    let secuencial = 1;
    if (ultimaEntrega) {
      const match = ultimaEntrega.codigo.match(/-(\d+)$/);
      if (match) {
        secuencial = parseInt(match[1]) + 1;
      }
    }

    return `ENT-${año}${mes}-${secuencial.toString().padStart(4, '0')}`;
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { PosicionContenedor } from '../entities/posicion-contenedor.entity';
import { PosicionVehiculo } from '../entities/posicion-vehiculo.entity';
import { PosicionBuque } from '../entities/posicion-buque.entity';

@Injectable()
export class GpsService {
  constructor(
    @InjectRepository(PosicionContenedor)
    private posicionContenedorRepository: Repository<PosicionContenedor>,
    @InjectRepository(PosicionVehiculo)
    private posicionVehiculoRepository: Repository<PosicionVehiculo>,
    @InjectRepository(PosicionBuque)
    private posicionBuqueRepository: Repository<PosicionBuque>,
  ) {}

  // perf(gps): paginacion en getPosicionesContenedores
  // Antes: LIMIT 100 fijo sin offset, forzaba al motor a ordenar toda la tabla
  //        y transferir siempre 100 filas aunque el llamador solo necesitara las primeras.
  // Ahora: LIMIT $1 OFFSET $2 con defaults (50, 0). El indice compuesto
  //        idx_posicion_contenedor_fecha (id_contenedor, fecha_hora) cubre el ORDER BY,
  //        y la reduccion de filas por pagina baja la presion sobre el buffer pool.
  async getPosicionesContenedores(limit = 50, offset = 0) {
    try {
      const rows = await this.posicionContenedorRepository.query(
        `
        SELECT
          id_posicion,
          id_contenedor,
          latitud,
          longitud,
          fecha_hora
        FROM monitoreo.posicioncontenedor
        ORDER BY fecha_hora DESC
        LIMIT $1 OFFSET $2
        `,
        [limit, offset],
      );

      return rows;
    } catch (error) {
      console.error('Error en getPosicionesContenedores:', error.message);
      return [];
    }
  }

  async getUltimaPosicionContenedor(id_contenedor: string) {
    try {
      const rows = await this.posicionContenedorRepository.query(
        `
        SELECT
          id_posicion,
          id_contenedor,
          latitud,
          longitud,
          fecha_hora
        FROM monitoreo.posicioncontenedor
        WHERE id_contenedor = $1
        ORDER BY fecha_hora DESC
        LIMIT 1
        `,
        [id_contenedor],
      );

      return rows[0] ?? null;
    } catch (error) {
      console.error('Error en getUltimaPosicionContenedor:', error.message);
      return null;
    }
  }

  async getHistorialPosicionesContenedor(id_contenedor: string, limit = 50) {
    try {
      const rows = await this.posicionContenedorRepository.query(
        `
        SELECT
          id_posicion,
          id_contenedor,
          latitud,
          longitud,
          fecha_hora
        FROM monitoreo.posicioncontenedor
        WHERE id_contenedor = $1
        ORDER BY fecha_hora DESC
        LIMIT $2
        `,
        [id_contenedor, limit],
      );

      return rows;
    } catch (error) {
      console.error('Error en getHistorialPosicionesContenedor:', error.message);
      return [];
    }
  }

  async getAllPosiciones() {
    try {
      const contRows = await this.posicionContenedorRepository.query(
        `
        SELECT DISTINCT ON (pc.id_contenedor)
          pc.id_posicion,
          pc.id_contenedor,
          pc.latitud,
          pc.longitud,
          pc.fecha_hora,
          c.codigo AS contenedor_codigo,
          ec.nombre AS estado_contenedor_nombre
        FROM monitoreo.posicioncontenedor pc
        JOIN shared.contenedor c ON c.id_contenedor = pc.id_contenedor
        LEFT JOIN shared.estadocontenedor ec ON ec.id_estado_contenedor = c.id_estado_contenedor
        ORDER BY pc.id_contenedor, pc.fecha_hora DESC
        `,
      );

      const vehiculos = await this.posicionVehiculoRepository
        .createQueryBuilder('pv')
        .leftJoinAndSelect('pv.vehiculo', 'v')
        .leftJoinAndSelect('v.estado_vehiculo', 'ev')
        .distinctOn(['pv.id_vehiculo'])
        .orderBy('pv.id_vehiculo')
        .addOrderBy('pv.fecha_hora', 'DESC')
        .getMany();

      const buques = await this.posicionBuqueRepository
        .createQueryBuilder('pb')
        .leftJoinAndSelect('pb.buque', 'b')
        .leftJoinAndSelect('b.estado_embarcacion', 'eb')
        .distinctOn(['pb.id_buque'])
        .orderBy('pb.id_buque')
        .addOrderBy('pb.fecha_hora', 'DESC')
        .getMany();

      const assetsContenedores = contRows.map((pc: any) => ({
        id: pc.id_posicion,
        code: pc.contenedor_codigo || `CNT-${pc.id_contenedor.substring(0, 8)}`,
        type: 'container',
        position: [Number(pc.latitud), Number(pc.longitud)],
        status: pc.estado_contenedor_nombre || 'Desconocido',
        statusColor: this.getStatusColor(pc.estado_contenedor_nombre),
        icon: 'inventory_2',
        lastUpdate: pc.fecha_hora,
        speed: 'N/A',
        temp: 'N/A',
      }));

      const assets = [
        ...assetsContenedores,
        ...vehiculos.map(pv => ({
          id: pv.id_posicion,
          code: pv.vehiculo?.placa || `VEH-${pv.id_vehiculo.substring(0, 8)}`,
          type: 'vehicle',
          position: [Number(pv.latitud), Number(pv.longitud)],
          status: pv.vehiculo?.estado_vehiculo?.nombre || 'Desconocido',
          statusColor: this.getVehiculoStatusColor(pv.vehiculo?.estado_vehiculo?.nombre),
          icon: 'local_shipping',
          lastUpdate: pv.fecha_hora,
          speed: 'N/A',
          temp: 'N/A',
        })),
        ...buques.map(pb => ({
          id: pb.id_posicion,
          code: pb.buque?.nombre || `BQE-${pb.id_buque.substring(0, 8)}`,
          type: 'ship',
          position: [Number(pb.latitud), Number(pb.longitud)],
          status: pb.buque?.estado_embarcacion?.nombre || 'Desconocido',
          statusColor: this.getBuqueStatusColor(pb.buque?.estado_embarcacion?.nombre),
          icon: 'sailing',
          lastUpdate: pb.fecha_hora,
          speed: 'N/A',
          temp: 'N/A',
        })),
      ];

      return assets;
    } catch (error) {
      console.error('Error en getAllPosiciones:', error.message);
      return [];
    }
  }

  private getStatusColor(status: string | undefined): string {
    if (!status) return '#6b7280';
    const key = status.toLowerCase();
    const colors: Record<string, string> = {
      'disponible':        '#10b981',
      'en transito':       '#3b82f6',
      'en puerto':         '#6366f1',
      'en reparacion':     '#f59e0b',
      'fuera de servicio': '#ef4444',
    };
    return colors[key] || '#6b7280';
  }

  private getVehiculoStatusColor(status: string | undefined): string {
    if (!status) return '#6b7280';
    const key = status.toLowerCase();
    const colors: Record<string, string> = {
      'disponible':        '#10b981',
      'en ruta':           '#3b82f6',
      'en mantenimiento':  '#f59e0b',
      'fuera de servicio': '#ef4444',
      'en revision':       '#8b5cf6',
    };
    return colors[key] || '#6b7280';
  }

  private getBuqueStatusColor(status: string | undefined): string {
    if (!status) return '#6b7280';
    const key = status.toLowerCase();
    const colors: Record<string, string> = {
      'operativo':         '#10b981',
      'en mantenimiento':  '#f59e0b',
      'fuera de servicio': '#ef4444',
      'en reparacion':     '#f97316',
      'disponible':        '#3b82f6',
    };
    return colors[key] || '#6b7280';
  }
}

import { Injectable, NotFoundException, BadRequestException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Importador } from '../entities/importador.entity';
import { ImportadorDireccion } from '../entities/importador-direccion.entity';

@Injectable()
export class ImportadoresService {
  constructor(
    @InjectRepository(Importador)
    private readonly importadorRepository: Repository<Importador>,
    @InjectRepository(ImportadorDireccion)
    private readonly direccionRepository: Repository<ImportadorDireccion>,
  ) {}

  async findOneDetalle(id: string) {
    try {
      const importador = await this.importadorRepository.findOne({
        where: { id_importador: id },
      });

      if (!importador) {
        throw new NotFoundException(`Importador con ID ${id} no encontrado`);
      }

      const direcciones = await this.direccionRepository.find({
        where: { id_importador: id },
        order: { principal: 'DESC', tipo: 'ASC' },
      });

      return {
        ...importador,
        direcciones,
      };
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      console.error('Error en findOneDetalle importador:', error.message);
      throw new Error('Error al obtener el detalle del importador');
    }
  }

  async createDireccion(id_importador: string, data: { direccion: string; tipo?: string | null; principal?: boolean }) {
    const importador = await this.importadorRepository.findOne({ where: { id_importador } });

    if (!importador) {
      throw new NotFoundException(`Importador con ID ${id_importador} no encontrado`);
    }

    const direccionTrim = (data.direccion || '').trim();
    if (!direccionTrim) {
      throw new BadRequestException('La dirección es obligatoria');
    }

    const esPrincipal = !!data.principal;

    if (esPrincipal) {
      // Si se marca como principal, desmarcar otras direcciones principales del mismo importador
      await this.direccionRepository.update({ id_importador, principal: true }, { principal: false });
    }

    const nueva = this.direccionRepository.create({
      id_importador,
      direccion: direccionTrim,
      tipo: data.tipo ?? null,
      principal: esPrincipal,
    });

    const guardada = await this.direccionRepository.save(nueva);

    return guardada;
  }
}

import { IncidenciasService } from './incidencias.service';

describe('IncidenciasService.update (RN-08)', () => {
  const incidenciaExistente = {
    id_incidencia: 'inc-1',
    codigo: 'INC-2611-0001',
    descripcion: 'Original',
    grado_severidad: 2,
    fecha_hora: new Date('2026-01-15T10:00:00.000Z'),
    id_usuario: 'user-alta',
    id_tipo_incidencia: 'tipo-1',
    id_estado_incidencia: 'estado-1',
    id_operacion: 'op-1',
