    estado_incidencia: { id_estado_incidencia: 'estado-1', nombre: 'Abierta' },
    operacion: { codigo: 'OP-1' },
  };

  let service: IncidenciasService;
  let incidenciaRepository: {
    findOne: jest.Mock;
    update: jest.Mock;
    remove: jest.Mock;
  };
  let tipoIncidenciaRepository: { findOne: jest.Mock };
  let estadoIncidenciaRepository: { findOne: jest.Mock };

  beforeEach(() => {
    incidenciaRepository = {
      findOne: jest.fn().mockResolvedValue(incidenciaExistente),
      update: jest.fn().mockResolvedValue({ affected: 1 }),
      remove: jest.fn(),
    };
    tipoIncidenciaRepository = {
      findOne: jest.fn().mockResolvedValue({ id_tipo_incidencia: 'tipo-2' }),
    };
    estadoIncidenciaRepository = {
      findOne: jest.fn().mockResolvedValue({ id_estado_incidencia: 'estado-2' }),
    };

    service = new IncidenciasService(
      incidenciaRepository as never,
      tipoIncidenciaRepository as never,
      estadoIncidenciaRepository as never,
    );
  });

  it('no persiste id_usuario ni fecha_hora aunque vengan en el body', async () => {
    await service.update('inc-1', {
      descripcion: 'Actualizada',
      grado_severidad: 4,
      id_tipo_incidencia: 'tipo-2',
      id_estado_incidencia: 'estado-2',
      id_usuario: 'atacante',
      fecha_hora: new Date('2099-01-01T00:00:00.000Z'),
    } as never);

    expect(incidenciaRepository.update).toHaveBeenCalledWith('inc-1', {
      descripcion: 'Actualizada',
      grado_severidad: 4,
      id_tipo_incidencia: 'tipo-2',
      id_estado_incidencia: 'estado-2',
    });
    expect(incidenciaRepository.update.mock.calls[0][1]).not.toHaveProperty(
      'id_usuario',
    );
    expect(incidenciaRepository.update.mock.calls[0][1]).not.toHaveProperty(
      'fecha_hora',
    );
  });

  it('no llama a repository.update si el body solo trae campos de auditoría', async () => {
    const resultado = await service.update('inc-1', {
      id_usuario: 'atacante',
      fecha_hora: new Date('2099-01-01T00:00:00.000Z'),
    } as never);

    expect(incidenciaRepository.update).not.toHaveBeenCalled();
    expect(resultado).toBe(incidenciaExistente);
  });

  it('no expone remove (método eliminado)', () => {
    expect(
      (service as unknown as { remove?: unknown }).remove,
    ).toBeUndefined();
  });
});

import { Injectable, NotFoundException, BadRequestException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Incidencia } from '../entities/incidencia.entity';
import { TipoIncidencia } from '../entities/tipo-incidencia.entity';
import { EstadoIncidencia } from '../entities/estado-incidencia.entity';

export interface CreateIncidenciaDto {
  id_tipo_incidencia: string;
  descripcion: string;
  grado_severidad: number;
  id_operacion: string;
  id_usuario?: string;
}

export interface UpdateIncidenciaDto {
  id_tipo_incidencia?: string;
  descripcion?: string;
  grado_severidad?: number;
  id_estado_incidencia?: string;
}

@Injectable()
export class IncidenciasService {
  constructor(
    @InjectRepository(Incidencia)
    private incidenciaRepository: Repository<Incidencia>,
    @InjectRepository(TipoIncidencia)
    private tipoIncidenciaRepository: Repository<TipoIncidencia>,
    @InjectRepository(EstadoIncidencia)
    private estadoIncidenciaRepository: Repository<EstadoIncidencia>,
  ) {}

  async findAll(filtros: any = {}) {
    try {
      const { tipo, estado, operacion, codigo, limite = 100, pagina = 1 } = filtros;

      const query = this.incidenciaRepository
        .createQueryBuilder('incidencia')
        .leftJoinAndSelect('incidencia.tipo_incidencia', 'tipo')
        .leftJoinAndSelect('incidencia.estado_incidencia', 'estado')
        .leftJoinAndSelect('incidencia.operacion', 'operacion')
        .orderBy('incidencia.fecha_hora', 'DESC');

      // Aplicar filtros
      if (tipo) {
        query.andWhere('incidencia.id_tipo_incidencia = :tipo', { tipo });
      }

      if (estado) {
        query.andWhere('incidencia.id_estado_incidencia = :estado', { estado });
      }

      if (operacion) {
        query.andWhere('incidencia.id_operacion = :operacion', { operacion });
      }

      if (codigo) {
        query.andWhere('LOWER(incidencia.codigo) LIKE :codigo', {
          codigo: `%${String(codigo).toLowerCase()}%`,
        });
      }

      // Paginación
      const skip = (pagina - 1) * limite;
      query.skip(skip).take(limite);

      const [incidencias, total] = await query.getManyAndCount();

      return {
        incidencias,
        total,
        pagina: Number(pagina),
        total_paginas: Math.ceil(total / limite),
        por_pagina: Number(limite),
      };
    } catch (error) {
      console.error('Error en findAll incidencias:', error.message);
      return {
        incidencias: [],
        total: 0,
        pagina: 1,
        total_paginas: 0,
        por_pagina: 100,
      };
    }
  }

  async findOne(id: string) {
    try {
      const incidencia = await this.incidenciaRepository.findOne({
        where: { id_incidencia: id },
        relations: ['tipo_incidencia', 'estado_incidencia', 'operacion'],
      });

      if (!incidencia) {
        throw new NotFoundException(`Incidencia con ID ${id} no encontrada`);
      }

      return incidencia;
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      console.error('Error en findOne incidencia:', error.message);
      throw new Error('Error al obtener la incidencia');
    }
  }

  /**
   * Rodaja vertical Lab06: el POST de incidencias usa RegistrarIncidenciaUseCase
   * + IncidenciasTypeormAdapter. Este create queda como legado / respaldo;
   * listar y update siguen aquí; delete ya no.
   */
  async create(data: CreateIncidenciaDto) {
    try {
      // Validar que venga un id_usuario (desde el contexto de autenticación)
      if (!data.id_usuario) {
        throw new BadRequestException('Usuario no autenticado');
      }

      // Validar que el tipo de incidencia existe
      const tipoExists = await this.tipoIncidenciaRepository.findOne({
        where: { id_tipo_incidencia: data.id_tipo_incidencia },
      });

      if (!tipoExists) {
        throw new BadRequestException('Tipo de incidencia no válido');
      }

      // Obtener el estado inicial (puedes ajustarlo según tu lógica)
      const estadoInicial = await this.estadoIncidenciaRepository.findOne({
        where: {}, // Obtener el primer estado o el que definas como "Abierta"
      });

      if (!estadoInicial) {
        throw new BadRequestException('No hay estados de incidencia configurados');
      }

      // Generar código único
      const codigo = await this.generarCodigoUnico();

      const incidencia = this.incidenciaRepository.create({
        ...data,
        codigo,
        id_estado_incidencia: estadoInicial.id_estado_incidencia,
        id_usuario: data.id_usuario,
      });

      const saved = await this.incidenciaRepository.save(incidencia);

      // Devolver con relaciones
      return await this.findOne(saved.id_incidencia);
    } catch (error) {
      if (error instanceof BadRequestException || error instanceof NotFoundException) {
        throw error;
      }
      console.error('Error en create incidencia:', error.message);
      throw new Error('Error al crear la incidencia');
    }
  }

  async update(id: string, data: UpdateIncidenciaDto = {}) {
    try {
      const incidencia = await this.findOne(id);

      if (data.id_tipo_incidencia) {
        const tipoExists = await this.tipoIncidenciaRepository.findOne({
          where: { id_tipo_incidencia: data.id_tipo_incidencia },
        });
        if (!tipoExists) {
          throw new BadRequestException('Tipo de incidencia no válido');
        }
      }

      if (data.id_estado_incidencia) {
        const estadoExists = await this.estadoIncidenciaRepository.findOne({
          where: { id_estado_incidencia: data.id_estado_incidencia },
        });
        if (!estadoExists) {
          throw new BadRequestException('Estado de incidencia no válido');
        }
      }

      const payload: UpdateIncidenciaDto = {};
      if (data.id_tipo_incidencia !== undefined) {
        payload.id_tipo_incidencia = data.id_tipo_incidencia;
      }
      if (data.descripcion !== undefined) {
        payload.descripcion = data.descripcion;
      }
      if (data.grado_severidad !== undefined) {
        payload.grado_severidad = data.grado_severidad;
      }
      if (data.id_estado_incidencia !== undefined) {
        payload.id_estado_incidencia = data.id_estado_incidencia;
      }

      if (Object.keys(payload).length === 0) {
        return incidencia;
      }

      await this.incidenciaRepository.update(id, payload);

      return await this.findOne(id);
    } catch (error) {
      if (
        error instanceof BadRequestException ||
        error instanceof NotFoundException
      ) {
        throw error;
      }
      console.error('Error en update incidencia:', error.message);
      throw new Error('Error al actualizar la incidencia');
    }
  }

  // Métodos auxiliares
  async getTiposIncidencia() {
    try {
      const tipos = await this.tipoIncidenciaRepository.find();
      console.log('Tipos de incidencia encontrados:', tipos.length);
      return tipos;
    } catch (error) {
      console.error('Error al obtener tipos de incidencia:', error.message);
      return [];
    }
  }

  async getEstadosIncidencia() {
    try {
      const estados = await this.estadoIncidenciaRepository.find();
      console.log('Estados de incidencia encontrados:', estados.length);
      return estados;
    } catch (error) {
      console.error('Error al obtener estados de incidencia:', error.message);
      return [];
    }
  }

  async getEstadisticas() {
    try {
      const total = await this.incidenciaRepository.count();

      const porTipo = await this.incidenciaRepository
        .createQueryBuilder('incidencia')
        .leftJoin('incidencia.tipo_incidencia', 'tipo')
        .select('tipo.nombre', 'tipo')
        .addSelect('COUNT(*)', 'cantidad')
        .groupBy('tipo.nombre')
        .getRawMany();

      const porEstado = await this.incidenciaRepository
        .createQueryBuilder('incidencia')
        .leftJoin('incidencia.estado_incidencia', 'estado')
        .select('estado.nombre', 'estado')
        .addSelect('COUNT(*)', 'cantidad')
        .groupBy('estado.nombre')
        .getRawMany();

      const porSeveridad = await this.incidenciaRepository
        .createQueryBuilder('incidencia')
        .select('incidencia.grado_severidad', 'severidad')
        .addSelect('COUNT(*)', 'cantidad')
        .groupBy('incidencia.grado_severidad')
        .getRawMany();

      return {
        total,
        por_tipo: porTipo,
        por_estado: porEstado,
        por_severidad: porSeveridad,
      };
    } catch (error) {
      console.error('Error en getEstadisticas incidencias:', error.message);
      return {
        total: 0,
        por_tipo: [],
        por_estado: [],
        por_severidad: [],
      };
    }
  }

  private async generarCodigoUnico(): Promise<string> {
    const fecha = new Date();
    const año = fecha.getFullYear().toString().slice(-2);
    const mes = (fecha.getMonth() + 1).toString().padStart(2, '0');
    
    // Contar incidencias del mes actual
    const count = await this.incidenciaRepository
      .createQueryBuilder('incidencia')
      .where('EXTRACT(YEAR FROM incidencia.fecha_hora) = :year', { year: fecha.getFullYear() })
      .andWhere('EXTRACT(MONTH FROM incidencia.fecha_hora) = :month', { month: fecha.getMonth() + 1 })
      .getCount();

    const secuencia = (count + 1).toString().padStart(4, '0');
    
    return `INC-${año}${mes}-${secuencia}`;
  }
}

import { Injectable, NotFoundException, BadRequestException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { MoreThanOrEqual, Repository } from 'typeorm';
import { Operacion } from '../../shared/entities/operacion.entity';
import { OperacionMonitoreo } from '../entities/operacion-monitoreo.entity';
import { Contenedor } from '../../shared/entities/contenedor.entity';
import { Vehiculo } from '../../shared/entities/vehiculo.entity';
import { Buque } from '../../shared/entities/buque.entity';
import { EstadoOperacion } from '../../shared/entities/estado-operacion.entity';
import { CreateOperacionDto } from '../dto/create-operacion.dto';
import { Notificacion } from '../entities/notificacion.entity';
import { Entrega } from '../entities/entrega.entity';
import { OperacionEmpleado } from '../../gestion_maritima/entities/operacion-empleado.entity';
import { OperacionContenedor } from '../../gestion_maritima/entities/operacion-contenedor.entity';
import { OperacionMaritima } from '../../shared/entities/operacion-maritima.entity';
import { Operador } from '../entities/operador.entity';
import { EstatusNavegacion } from '../../shared/entities/estatus-navegacion.entity';
import { OperacionTerrestre } from '../../operaciones_terrestres/entities/operacion-terrestre.entity';
import { OperacionTerrestreDetalle } from '../../operaciones_terrestres/entities/operacion-terrestre-detalle.entity';

@Injectable()
export class OperacionesService {
  constructor(
    @InjectRepository(Operacion)
    private operacionRepository: Repository<Operacion>,
    @InjectRepository(OperacionMonitoreo)
    private operacionMonitoreoRepository: Repository<OperacionMonitoreo>,
    @InjectRepository(EstadoOperacion)
    private estadoOperacionRepository: Repository<EstadoOperacion>,
    @InjectRepository(Contenedor)
    private contenedorRepository: Repository<Contenedor>,
    @InjectRepository(Vehiculo)
    private vehiculoRepository: Repository<Vehiculo>,
    @InjectRepository(Buque)
    private buqueRepository: Repository<Buque>,
    @InjectRepository(Notificacion)
    private notificacionRepository: Repository<Notificacion>,
    @InjectRepository(Entrega)
    private entregaRepository: Repository<Entrega>,
    @InjectRepository(OperacionEmpleado)
    private operacionEmpleadoRepository: Repository<OperacionEmpleado>,
    @InjectRepository(OperacionContenedor)
    private operacionContenedorRepository: Repository<OperacionContenedor>,
    @InjectRepository(OperacionMaritima)
    private operacionMaritimaRepository: Repository<OperacionMaritima>,
    @InjectRepository(Operador)
    private operadorRepository: Repository<Operador>,
    @InjectRepository(EstatusNavegacion)
    private estatusNavegacionRepository: Repository<EstatusNavegacion>,
    @InjectRepository(OperacionTerrestre)
    private operacionTerrestreRepository: Repository<OperacionTerrestre>,
    @InjectRepository(OperacionTerrestreDetalle)
    private operacionTerrestreDetalleRepository: Repository<OperacionTerrestreDetalle>,
  ) {}

  async findAll(estado?: string) {
    try {
      // Consulta base de operaciones usando SQL explícito sobre shared.operacion
      // Si se envía "estado", se filtra por nombre de estado; caso contrario trae todas
      const rows: Array<{
        id_operacion: string;
        codigo: string;
        fecha_inicio: Date;
        fecha_fin: Date | null;
        id_estado_operacion: string;
        estado_nombre: string;
      }> = await this.operacionRepository.query(
        `
        SELECT 
          o.id_operacion,
          o.codigo,
          o.fecha_inicio,
          o.fecha_fin,
          eo.id_estado_operacion,
          eo.nombre AS estado_nombre
        FROM shared.operacion o
        JOIN shared.estadooperacion eo 
          ON o.id_estado_operacion = eo.id_estado_operacion
        WHERE ($1::text IS NULL OR eo.nombre = $1)
        ORDER BY o.fecha_inicio DESC
        `,
        [estado ?? null],
      );

      // Adaptar filas crudas al mismo shape que devolvía TypeORM (incluyendo estado_operacion)
      const operacionesBase = rows.map((row) => ({
        id_operacion: row.id_operacion,
        codigo: row.codigo,
        fecha_inicio: row.fecha_inicio,
        fecha_fin: row.fecha_fin,
        id_estado_operacion: row.id_estado_operacion,
        estado_operacion: {
          id_estado_operacion: row.id_estado_operacion,
          nombre: row.estado_nombre,
        },
      })) as any[];

      // Enriquecer cada operación con operador, buque y cantidad de contenedores
      const enriquecidas = [] as any[];

      for (const op of operacionesBase) {
        // Operador asignado
        const relacionEmpleado = await this.operacionEmpleadoRepository.findOne({
          where: { id_operacion: op.id_operacion },
          order: { fecha_asignacion: 'DESC' },
        });

        let operadorInfo: any = null;
        if (relacionEmpleado) {
          const operador = await this.operadorRepository.findOne({
            where: { id_empleado: relacionEmpleado.id_empleado },
            relations: ['empleado'],
          });

          if (operador?.empleado) {
            operadorInfo = {
              nombre: `${operador.empleado.nombre} ${operador.empleado.apellido}`,
            };
          }
        }

        // Buque asociado (operación marítima)
        const operacionMaritima = await this.operacionMaritimaRepository.findOne({
          where: { id_operacion: op.id_operacion },
          relations: ['buque'],
        });

        const buqueInfo = operacionMaritima && operacionMaritima.buque
          ? {
              nombre: operacionMaritima.buque.nombre,
            }
          : null;

        // Vehículo asociado (operación terrestre) - solo lectura, si ya existe
        let vehiculoInfo: any = null;
        const opTerrestre = await this.operacionTerrestreRepository.findOne({
          where: { id_operacion: op.id_operacion },
        });

        if (opTerrestre) {
          const detalle = await this.operacionTerrestreDetalleRepository.findOne({
            where: { id_operacion_terrestre: opTerrestre.id_operacion_terrestre },
            relations: ['vehiculo'],
          });

          if (detalle?.vehiculo) {
            vehiculoInfo = {
              placa: detalle.vehiculo.placa,
            };
          }
        }

        // Cantidad real de contenedores asignados
        const cantidadContenedores = await this.operacionContenedorRepository.count({
          where: { id_operacion: op.id_operacion },
        });

        enriquecidas.push({
          ...op,
          operador: operadorInfo,
          buque: buqueInfo,
          vehiculo: vehiculoInfo,
          contenedores_count: cantidadContenedores,
        });
      }

      return enriquecidas;
    } catch (error) {
      console.error('Error en findAll operaciones:', error.message);
      return [];
    }
  }

  async findOne(id: string) {
    const operacion = await this.operacionRepository.findOne({
      where: { id_operacion: id },
      relations: ['estado_operacion'],
    });

    if (!operacion) {
      throw new NotFoundException(`Operación con ID ${id} no encontrada`);
    }

    // Operador asignado (a través de gestion_maritima.operacionempleado -> monitoreo.operador)
    const relacionEmpleado = await this.operacionEmpleadoRepository.findOne({
      where: { id_operacion: id },
      order: { fecha_asignacion: 'DESC' },
    });

    let operadorInfo: any = null;
    if (relacionEmpleado) {
      const operador = await this.operadorRepository.findOne({
        where: { id_empleado: relacionEmpleado.id_empleado },
        relations: ['empleado'],
      });

      if (operador?.empleado) {
        operadorInfo = {
          id_operador: operador.id_operador,
          nombre: `${operador.empleado.nombre} ${operador.empleado.apellido}`,
        };
      }
    }

    // Transporte marítimo (buque) a través de shared.operacionmaritima
    const operacionMaritima = await this.operacionMaritimaRepository.findOne({
      where: { id_operacion: id },
      relations: ['buque'],
    });

    const buqueInfo = operacionMaritima && operacionMaritima.buque
      ? {
          id_buque: operacionMaritima.buque.id_buque,
          nombre: operacionMaritima.buque.nombre,
          matricula: operacionMaritima.buque.matricula,
        }
      : null;

    // Transporte terrestre (vehículo) a través de shared.operacionterrestre + operaciones_terrestres.operacionterrestredetalle
    let vehiculoInfo: any = null;
    const opTerrestre = await this.operacionTerrestreRepository.findOne({
      where: { id_operacion: id },
    });

    if (opTerrestre) {
      const detalle = await this.operacionTerrestreDetalleRepository.findOne({
        where: { id_operacion_terrestre: opTerrestre.id_operacion_terrestre },
        relations: ['vehiculo'],
      });

      if (detalle?.vehiculo) {
        vehiculoInfo = {
          id_vehiculo: detalle.vehiculo.id_vehiculo,
          placa: detalle.vehiculo.placa,
        };
      }
    }

    // Contenedores asignados (gestion_maritima.operacioncontenedor -> shared.contenedor)
    const relacionesContenedores = await this.operacionContenedorRepository.find({
      where: { id_operacion: id },
      relations: ['contenedor', 'contenedor.tipo_contenedor'],
    });

    const contenedores = relacionesContenedores.map((rel) => ({
      codigo: rel.contenedor?.codigo,
      tipo: rel.contenedor?.tipo_contenedor?.nombre,
    }));

    return {
      ...operacion,
      descripcion: null,
      operador: operadorInfo,
      vehiculo: vehiculoInfo,
      buque: buqueInfo,
      contenedores,
    };
  }

  async create(createOperacionDto: CreateOperacionDto) {
    // Determinar estado inicial de la operación
    let estadoId: string | null = null;

    // Si el frontend envía un estado específico, lo usamos directamente
    if (createOperacionDto.id_estado_operacion) {
      estadoId = createOperacionDto.id_estado_operacion;
    } else {
      // Si no, tomamos el primer estado disponible como valor por defecto
      const primerEstado = await this.estadoOperacionRepository.findOne({
        order: { nombre: 'ASC' },
      });

      if (!primerEstado) {
        throw new Error('No hay estados de operación configurados en la base de datos.');
      }

      estadoId = primerEstado.id_estado_operacion;
    }

    // Crear la operación
    const operacion = this.operacionRepository.create({
      codigo: createOperacionDto.codigo,
      fecha_inicio: new Date(createOperacionDto.fecha_inicio),
      id_estado_operacion: estadoId,
    });

    const savedOperacion = await this.operacionRepository.save(operacion);

    // Crear la operación de monitoreo
    const operacionMonitoreo = this.operacionMonitoreoRepository.create({
      id_operacion: savedOperacion.id_operacion,
    });
    await this.operacionMonitoreoRepository.save(operacionMonitoreo);

    // Registrar operador (si se envió)
    if (createOperacionDto.operador_id) {
      const operador = await this.operadorRepository.findOne({
        where: { id_operador: createOperacionDto.operador_id },
      });

      if (operador) {
        const relacion = this.operacionEmpleadoRepository.create({
          id_operacion: savedOperacion.id_operacion,
          id_empleado: operador.id_empleado,
        });
        await this.operacionEmpleadoRepository.save(relacion);
      }
    }

    // Registrar operación marítima si el medio de transporte es buque
    if (createOperacionDto.medio_transporte === 'buque' && createOperacionDto.buque_id) {
      // Estatus de navegación por defecto (primer registro disponible)
      const [estatus] = await this.estatusNavegacionRepository.find({
        order: { nombre: 'ASC' },
        take: 1,
      });

      const operacionMaritima = this.operacionMaritimaRepository.create({
        id_operacion: savedOperacion.id_operacion,
        codigo: `OM-${savedOperacion.codigo}`,
        cantidad_contenedores: createOperacionDto.contenedores?.length || 0,
        id_estatus_navegacion: estatus?.id_estatus_navegacion,
        id_buque: createOperacionDto.buque_id,
        porcentaje_trayecto: 0,
      });

      await this.operacionMaritimaRepository.save(operacionMaritima);
    }

    // Registrar contenedores asignados (por código)
    if (createOperacionDto.contenedores && createOperacionDto.contenedores.length > 0) {
      for (const codigo of createOperacionDto.contenedores) {
        const contenedor = await this.contenedorRepository.findOne({ where: { codigo } });
        if (contenedor) {
          const relacion = this.operacionContenedorRepository.create({
            id_operacion: savedOperacion.id_operacion,
            id_contenedor: contenedor.id_contenedor,
          });
          await this.operacionContenedorRepository.save(relacion);
        }
      }
    }

    return savedOperacion;
  }

  async update(id: string, updateData: any) {
    const operacion = await this.findOne(id);

    // Actualizar campos permitidos
    if (updateData.codigo) operacion.codigo = updateData.codigo;
    if (updateData.fecha_inicio) operacion.fecha_inicio = new Date(updateData.fecha_inicio);
    if (updateData.fecha_fin) operacion.fecha_fin = new Date(updateData.fecha_fin);
    if (updateData.id_estado_operacion) operacion.id_estado_operacion = updateData.id_estado_operacion;

    return await this.operacionRepository.save(operacion);
  }

  async finalize(id: string) {
    // Cargar la entidad real de Operacion con su estado actual
    const operacion = await this.operacionRepository.findOne({
      where: { id_operacion: id },
      relations: ['estado_operacion'],
    });

    if (!operacion) {
      throw new NotFoundException(`Operación con ID ${id} no encontrada`);
    }

    // Validar que la operación esté en un estado que permita finalizarse
    const estadoActual = operacion.estado_operacion?.nombre?.toLowerCase() || '';
    const puedeFinalizar = estadoActual === 'en curso' || estadoActual === 'en espera';

    if (!puedeFinalizar) {
      throw new BadRequestException(
        'Solo se pueden finalizar operaciones en estado "En Curso" o "En Espera".',
      );
    }

    const estadoCompletada = await this.estadoOperacionRepository.findOne({
      where: { nombre: 'Completada' },
    });

    if (!estadoCompletada) {
      throw new Error('Estado "Completada" no encontrado. Por favor, ejecuta los seeders para poblar los estados.');
    }

    const ahora = new Date();

    await this.operacionRepository.update(
      { id_operacion: id },
      {
        fecha_fin: ahora,
        id_estado_operacion: estadoCompletada.id_estado_operacion,
      },
    );

    // Devolver la operación actualizada (incluyendo el nuevo estado)
    const operacionActualizada = await this.operacionRepository.findOne({
      where: { id_operacion: id },
      relations: ['estado_operacion'],
    });

    return operacionActualizada;
  }

  async remove(id: string) {
    const operacion = await this.findOne(id);

    // Eliminar primero las relaciones en gestion_maritima.operacionempleado para no violar la FK
    await this.operacionEmpleadoRepository.delete({ id_operacion: id });

    // Eliminar también las relaciones en gestion_maritima.operacioncontenedor
    await this.operacionContenedorRepository.delete({ id_operacion: id });

    // Eliminar relaciones en shared.operacionmaritima (y en cascada sus tablas dependientes por id_operacion_maritima)
    await this.operacionMaritimaRepository.delete({ id_operacion: id });

    await this.operacionRepository.remove(operacion);
    return { message: 'Operación eliminada exitosamente', id };
  }

  async getKPIs() {
    try {
      // Obtener el estado "En Curso"
      const estadoEnCurso = await this.estadoOperacionRepository.findOne({
        where: { nombre: 'En Curso' },
      });

      let operacionesActivas = 0;

      if (estadoEnCurso) {
        operacionesActivas = await this.operacionRepository.count({
          where: { id_estado_operacion: estadoEnCurso.id_estado_operacion },
        });
      }

      // Contenedores en tránsito (estado "En Transito")
      const contenedoresTransito = await this.contenedorRepository
        .createQueryBuilder('c')
        .leftJoin('c.estado_contenedor', 'ec')
        .where('LOWER(ec.nombre) = :estado', { estado: 'en transito' })
        .getCount();

      // Alertas pendientes: notificaciones de los últimos 7 días (SQL explícito)
      const haceSieteDias = new Date();
      haceSieteDias.setDate(haceSieteDias.getDate() - 7);

      const alertasRows = await this.notificacionRepository.query(
        `
        SELECT COUNT(*)::int AS total
        FROM monitoreo.notificacion
        WHERE fecha_hora >= $1
        `,
        [haceSieteDias],
      );

      const alertasPendientes =
        alertasRows && alertasRows.length > 0
          ? Number(alertasRows[0].total) || 0
          : 0;

      // Entregas de hoy
      const hoy = new Date();
      const inicioDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate());
      const finDia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate(), 23, 59, 59, 999);

      const entregasHoy = await this.entregaRepository
        .createQueryBuilder('entrega')
        .where('entrega.fecha_entrega >= :inicio', { inicio: inicioDia })
        .andWhere('entrega.fecha_entrega <= :fin', { fin: finDia })
        .getCount();

      return {
        operaciones_activas: operacionesActivas,
        contenedores_transito: contenedoresTransito,
        alertas_pendientes: alertasPendientes,
        entregas_hoy: entregasHoy,
      };
    } catch (error) {
      console.error('Error en getKPIs:', error);
      // Devolver valores por defecto en caso de error
      return {
        operaciones_activas: 0,
        contenedores_transito: 0,
        alertas_pendientes: 0,
        entregas_hoy: 0,
      };
    }
  }

  async getOperacionesPorEstado() {
    try {
      const resultado = await this.operacionRepository
        .createQueryBuilder('o')
        .leftJoin('o.estado_operacion', 'eo')
        .select('eo.nombre', 'estado')
        .addSelect('COUNT(o.id_operacion)', 'cantidad')
        .groupBy('eo.nombre')
        .orderBy('cantidad', 'DESC')
        .getRawMany();

      return resultado.map(item => ({
        estado: item.estado,
        cantidad: parseInt(item.cantidad),
      }));
    } catch (error) {
      console.error('Error en getOperacionesPorEstado:', error);
      return [];
    }
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { EstadoOperacion } from '../../shared/entities/estado-operacion.entity';
import { Operador } from '../entities/operador.entity';
import { Vehiculo } from '../../shared/entities/vehiculo.entity';
import { Buque } from '../../shared/entities/buque.entity';
import { Ruta } from '../../shared/entities/ruta.entity';
import { Puerto } from '../../gestion_maritima/entities/puerto.entity';
import { Muelle } from '../../gestion_maritima/entities/muelle.entity';
import { RutaMaritima } from '../../gestion_maritima/entities/ruta-maritima.entity';
import { RutaPuertoIntermedio } from '../../gestion_maritima/entities/ruta-puerto-intermedio.entity';

@Injectable()
export class RecursosService {
  constructor(
    @InjectRepository(EstadoOperacion)
    private estadoOperacionRepository: Repository<EstadoOperacion>,
    @InjectRepository(Operador)
    private operadorRepository: Repository<Operador>,
    @InjectRepository(Vehiculo)
    private vehiculoRepository: Repository<Vehiculo>,
    @InjectRepository(Buque)
    private buqueRepository: Repository<Buque>,
    @InjectRepository(Puerto)
    private puertoRepository: Repository<Puerto>,
    @InjectRepository(Muelle)
    private muelleRepository: Repository<Muelle>,
    @InjectRepository(Ruta)
    private rutaRepository: Repository<Ruta>,
    @InjectRepository(RutaMaritima)
    private rutaMaritimaRepository: Repository<RutaMaritima>,
    @InjectRepository(RutaPuertoIntermedio)
    private rutaPuertoIntermedioRepository: Repository<RutaPuertoIntermedio>,
  ) {}

  async findEstados() {
    try {
      return await this.estadoOperacionRepository.find({
        order: { nombre: 'ASC' },
      });
    } catch (error) {
      console.error('Error al obtener estados:', error);
      return [];
    }
  }

  async findOperadores() {
    try {
      return await this.operadorRepository.find({
        relations: ['empleado'],
        order: { turno: 'ASC' },
      });
    } catch (error) {
      console.error('Error al obtener operadores:', error);
      return [];
    }
  }

  async findVehiculos() {
    try {
      // Solo vehículos con estado 'Disponible'
      return await this.vehiculoRepository
        .createQueryBuilder('v')
        .leftJoinAndSelect('v.estado_vehiculo', 'ev')
        .where('LOWER(ev.nombre) = :estado', { estado: 'disponible' })
        .orderBy('v.placa', 'ASC')
        .getMany();
    } catch (error) {
      console.error('Error al obtener vehículos:', error);
      return [];
    }
  }

  async findBuques() {
    try {
      // Solo buques con estado 'Disponible'
      return await this.buqueRepository
        .createQueryBuilder('b')
        .leftJoinAndSelect('b.estado_embarcacion', 'ee')
        .where('LOWER(ee.nombre) = :estado', { estado: 'disponible' })
        .orderBy('b.nombre', 'ASC')
        .getMany();
    } catch (error) {
      console.error('Error al obtener buques:', error);
      return [];
    }
  }

  async findBuqueById(id: string) {
    try {
      return await this.buqueRepository.findOne({ where: { id_buque: id } });
    } catch (error) {
      console.error('Error al obtener buque por id:', error);
      return null;
    }
  }

  async findPuertos() {
    try {
      return await this.puertoRepository.find({
        order: { nombre: 'ASC' },
      });
    } catch (error) {
      console.error('Error al obtener puertos:', error);
      return [];
    }
  }

  async findMuellesByPuerto(id_puerto: string) {
    try {
      return await this.muelleRepository.find({
        where: { id_puerto },
        order: { codigo: 'ASC' },
      });
    } catch (error) {
      console.error('Error al obtener muelles por puerto:', error);
      return [];
    }
  }

  async findRutasMaritimasBetweenPuertos(id_puerto_origen: string, id_puerto_destino: string) {
    try {
      const rutas = await this.rutaMaritimaRepository.find({
        where: {
          id_puerto_origen,
          id_puerto_destino,
        },
        relations: ['ruta', 'puertos_intermedios', 'puertos_intermedios.puerto'],
        order: { codigo: 'ASC' },
      });

      return rutas.map((ruta) => ({
        id: ruta.id_ruta_maritima,
        codigo: ruta.codigo,
        distancia: ruta.distancia,
        duracion: ruta.ruta?.duracion ?? null,
        tarifa: ruta.ruta?.tarifa ?? null,
        puertosIntermedios:
          ruta.puertos_intermedios?.map((ri) => ri.puerto?.nombre).filter(Boolean) || [],
      }));
    } catch (error) {
      console.error('Error al obtener rutas marítimas entre puertos:', error);
      return [];
    }
  }

  async findRutaMaritimaById(id: string) {
    try {
      const ruta = await this.rutaMaritimaRepository.findOne({
        where: { id_ruta_maritima: id },
        relations: [
          'puerto_origen',
          'puerto_destino',
          'puertos_intermedios',
          'puertos_intermedios.puerto',
        ],
      });

      if (!ruta) {
        return null;
      }

      const puertos = [] as {
        tipo: 'origen' | 'intermedio' | 'destino';
        nombre: string;
        direccion: string;
      }[];

      if (ruta.puerto_origen) {
        puertos.push({
          tipo: 'origen',
          nombre: ruta.puerto_origen.nombre,
          direccion: ruta.puerto_origen.direccion,
        });
      }

      if (ruta.puertos_intermedios) {
        for (const intermedio of ruta.puertos_intermedios) {
          if (intermedio.puerto) {
            puertos.push({
              tipo: 'intermedio',
              nombre: intermedio.puerto.nombre,
              direccion: intermedio.puerto.direccion,
            });
          }
        }
      }

      if (ruta.puerto_destino) {
        puertos.push({
          tipo: 'destino',
          nombre: ruta.puerto_destino.nombre,
          direccion: ruta.puerto_destino.direccion,
        });
      }

      return {
        id: ruta.id_ruta_maritima,
        codigo: ruta.codigo,
        puertos,
      };
    } catch (error) {
      console.error('Error al obtener ruta marítima por id:', error);
      return null;
    }
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { DataSource, In, Repository } from 'typeorm';
import { Reporte } from '../entities/reporte.entity';
import { IncidenciaReporte } from '../entities/incidencia-reporte.entity';
import { Incidencia } from '../entities/incidencia.entity';
import { Operacion } from '../../shared/entities/operacion.entity';
import { Notificacion } from '../entities/notificacion.entity';
import { Contenedor } from '../../shared/entities/contenedor.entity';

export interface CreateReporteDto {
  detalle: string;
  fecha_reporte?: Date;
}

export interface UpdateReporteDto {
  detalle?: string;
  fecha_reporte?: Date;
}

@Injectable()
export class ReportesService {
  constructor(
    @InjectRepository(Reporte)
    private reporteRepository: Repository<Reporte>,
    @InjectRepository(IncidenciaReporte)
    private incidenciaReporteRepository: Repository<IncidenciaReporte>,
    @InjectRepository(Incidencia)
    private incidenciaRepository: Repository<Incidencia>,
    @InjectRepository(Operacion)
    private operacionRepository: Repository<Operacion>,
    @InjectRepository(Notificacion)
    private notificacionRepository: Repository<Notificacion>,
    @InjectRepository(Contenedor)
    private contenedorRepository: Repository<Contenedor>,
    private readonly dataSource: DataSource,
  ) {}

  // Listar todos los reportes con paginación y filtros
  async findAll(filtros: any = {}) {
    try {
      const { limite = 20, pagina = 1, desde, hasta } = filtros;

      const query = this.reporteRepository
        .createQueryBuilder('reporte')
        .orderBy('reporte.fecha_reporte', 'DESC');

      // Filtros de fecha
      if (desde) {
        query.andWhere('reporte.fecha_reporte >= :desde', { desde });
      }
      if (hasta) {
        query.andWhere('reporte.fecha_reporte <= :hasta', { hasta });
      }

      const skip = (pagina - 1) * limite;
      query.skip(skip).take(limite);

      const [reportes, total] = await query.getManyAndCount();

      return {
        reportes,
        total,
        pagina: Number(pagina),
        total_paginas: Math.ceil(total / limite),
        por_pagina: Number(limite),
      };
    } catch (error) {
      console.error('Error en findAll reportes:', error.message);
      return {
        reportes: [],
        total: 0,
        pagina: 1,
        total_paginas: 0,
        por_pagina: 20,
      };
    }
  }

  // Ejecutar proceso batch de cierre diario (esquema analítico)
  async ejecutarCierreDiario(fecha_corte?: string) {
    try {
      const hoy = new Date();
      const fecha = fecha_corte ? new Date(fecha_corte) : hoy;

      // Normalizar a solo fecha (YYYY-MM-DD)
      const fechaStr = fecha.toISOString().slice(0, 10);

      await this.dataSource.query(
        'SELECT monitoreo_analytics.f_cierre_diario_operaciones($1)',
        [fechaStr],
      );

      return {
        message: 'Proceso batch de cierre diario ejecutado correctamente',
        fecha_corte: fechaStr,
      };
    } catch (error: any) {
      console.error('Error al ejecutar cierre diario analítico:', error.message || error);
      throw new Error('Error al ejecutar el proceso batch de cierre diario');
    }
  }

  // Ejecutar proceso batch analítico para un rango de 120 días hasta la fecha indicada
  async ejecutarCierreRango120Dias(fecha_fin?: string) {
    try {
      const hoy = new Date();
      const fechaFin = fecha_fin ? new Date(fecha_fin) : hoy;

      // Normalizar fecha fin a solo fecha (YYYY-MM-DD)
      const fechaFinStr = fechaFin.toISOString().slice(0, 10);

      // Calcular fecha de inicio (120 días incluyendo la fecha fin: 119 días hacia atrás)
      const fechaInicio = new Date(fechaFin);
      fechaInicio.setDate(fechaInicio.getDate() - 119);
      const fechaInicioStr = fechaInicio.toISOString().slice(0, 10);

      await this.dataSource.query(
        'SELECT monitoreo_analytics.f_cierre_rango_fechas($1, $2)',
        [fechaInicioStr, fechaFinStr],
      );

      return {
        message:
          'Proceso batch analítico de los últimos 120 días ejecutado correctamente',
        fecha_inicio: fechaInicioStr,
        fecha_fin: fechaFinStr,
      };
    } catch (error: any) {
      console.error(
        'Error al ejecutar cierre analítico de rango 120 días:',
        error.message || error,
      );
      throw new Error(
        'Error al ejecutar el proceso batch de cierre analítico de 120 días',
      );
    }
  }

  // Obtener un reporte por ID
  async findOne(id: string) {
    try {
      const reporte = await this.reporteRepository.findOne({
        where: { id_reporte: id },
      });

      if (!reporte) {
        throw new NotFoundException(`Reporte con ID ${id} no encontrado`);
      }

      return reporte;
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      console.error('Error en findOne reporte:', error.message);
      throw new Error('Error al obtener el reporte');
    }
  }

  // Crear nuevo reporte
  async create(data: CreateReporteDto) {
    try {
      // Generar código único
      const codigo = await this.generarCodigo();

      const reporte = this.reporteRepository.create({
        codigo,
        detalle: data.detalle,
        fecha_reporte: data.fecha_reporte || new Date(),
      });

      return await this.reporteRepository.save(reporte);
    } catch (error) {
      console.error('Error en create reporte:', error.message);
      throw new Error('Error al crear el reporte');
    }
  }

  // Crear reporte asociado a una operación y a un conjunto de incidencias
  async crearReporteOperacion(
    id_operacion: string,
    incidenciasIds: string[] = [],
    comentarioAdicional?: string,
  ) {
    // 1) Obtener operación
    const operacion = await this.operacionRepository.findOne({
      where: { id_operacion },
    });

    if (!operacion) {
      throw new Error(`Operación con ID ${id_operacion} no encontrada`);
    }

    // 2) Obtener incidencias de la operación (filtrando por ids si se envían)
    const where: any = { id_operacion };
    if (incidenciasIds && incidenciasIds.length > 0) {
      where.id_incidencia = In(incidenciasIds);
    }

    const incidencias = await this.incidenciaRepository.find({
      where,
      relations: ['tipo_incidencia', 'estado_incidencia'],
      order: { fecha_hora: 'ASC' },
    });

    // 3) Construir detalle del reporte
    const lineas: string[] = [];
    lineas.push(`REPORTE DE OPERACIÓN ${operacion.codigo}`);
    lineas.push('');
    lineas.push(`ID Operación: ${operacion.id_operacion}`);
    if (operacion.fecha_inicio) {
      lineas.push(`Fecha inicio: ${operacion.fecha_inicio.toISOString()}`);
    }
    if (operacion.fecha_fin) {
      lineas.push(`Fecha fin: ${operacion.fecha_fin.toISOString()}`);
    }
    lineas.push('');
    lineas.push(`Incidencias incluidas: ${incidencias.length}`);

    incidencias.forEach((inc) => {
      const tipo = inc.tipo_incidencia?.nombre || 'N/A';
      const estado = inc.estado_incidencia?.nombre || 'N/A';
      lineas.push(
        `- ${inc.codigo} [${tipo}] (Severidad: ${inc.grado_severidad}, Estado: ${estado}) - ${inc.descripcion}`,
      );
    });

    if (comentarioAdicional) {
      lineas.push('');
      lineas.push('Comentarios adicionales:');
      lineas.push(comentarioAdicional);
    }

    const detalle = lineas.join('\n');

    // 4) Crear reporte
    const reporte = await this.create({ detalle });

    // 5) Registrar relaciones IncidenciaReporte
    if (incidencias.length > 0) {
      const relaciones = incidencias.map((inc) =>
        this.incidenciaReporteRepository.create({
          id_incidencia: inc.id_incidencia,
          id_reporte: reporte.id_reporte,
        }),
      );

      await this.incidenciaReporteRepository.save(relaciones);
    }

    return reporte;
  }

  // Crear reporte asociado a un contenedor y un conjunto de notificaciones de sensores
  async crearReporteContenedor(
    id_contenedor: string,
    notificacionesIds: string[] = [],
    comentarioAdicional?: string,
  ) {
    // 1) Obtener contenedor
    const contenedor = await this.contenedorRepository.findOne({
      where: { id_contenedor },
      relations: ['estado_contenedor', 'tipo_contenedor'],
    });

    if (!contenedor) {
      throw new Error(`Contenedor con ID ${id_contenedor} no encontrado`);
    }

    // 2) Obtener notificaciones del contenedor (filtrando por ids si se envían)
    const query = this.notificacionRepository
      .createQueryBuilder('notificacion')
      .leftJoinAndSelect('notificacion.tipo_notificacion', 'tipo_notificacion')
      .leftJoinAndSelect('notificacion.sensor', 'sensor')
      .leftJoinAndSelect('sensor.tipo_sensor', 'tipo_sensor')
      .leftJoinAndSelect('sensor.contenedor', 'contenedor')
      .where('contenedor.id_contenedor = :id_contenedor', { id_contenedor })
      .orderBy('notificacion.fecha_hora', 'ASC');

    if (notificacionesIds && notificacionesIds.length > 0) {
      query.andWhere('notificacion.id_notificacion IN (:...ids)', {
        ids: notificacionesIds,
      });
    }

    const notificaciones = await query.getMany();

    // 3) Construir detalle del reporte
    const lineas: string[] = [];
    lineas.push(`REPORTE DE CONTENEDOR ${contenedor.codigo}`);
    lineas.push('');
    lineas.push(`ID Contenedor: ${contenedor.id_contenedor}`);
    lineas.push(`Tipo: ${contenedor.tipo_contenedor?.nombre || 'N/A'}`);
    lineas.push(`Estado: ${contenedor.estado_contenedor?.nombre || 'N/A'}`);
    lineas.push('');
    lineas.push(`Notificaciones incluidas: ${notificaciones.length}`);

    notificaciones.forEach((n) => {
      const tipo = n.tipo_notificacion?.nombre || 'N/A';
      const sensorCodigo = n.sensor?.codigo || 'N/A';
      const sensorTipo = n.sensor?.tipo_sensor?.nombre || 'N/A';
      lineas.push(
        `- ${n.codigo} [${tipo}] Sensor: ${sensorCodigo} (${sensorTipo}) Valor: ${n.valor} Fecha: ${n.fecha_hora.toISOString()}`,
      );
    });

    if (comentarioAdicional) {
      lineas.push('');
      lineas.push('Comentarios adicionales:');
      lineas.push(comentarioAdicional);
    }

    const detalle = lineas.join('\n');

    // 4) Crear reporte
    const reporte = await this.create({ detalle });

    // 5) Actualizar notificaciones para vincularlas con el reporte
    if (notificaciones.length > 0) {
      const ids = notificaciones.map((n) => n.id_notificacion);
      await this.notificacionRepository.update(
        { id_notificacion: In(ids) },
        { id_reporte: reporte.id_reporte },
      );
    }

    return reporte;
  }

  // Actualizar reporte
  async update(id: string, data: UpdateReporteDto) {
    try {
      const reporte = await this.findOne(id);

      if (data.detalle !== undefined) {
        reporte.detalle = data.detalle;
      }
      if (data.fecha_reporte !== undefined) {
        reporte.fecha_reporte = data.fecha_reporte;
      }

      return await this.reporteRepository.save(reporte);
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      console.error('Error en update reporte:', error.message);
      throw new Error('Error al actualizar el reporte');
    }
  }

  // Eliminar reporte
  async remove(id: string) {
    try {
      const reporte = await this.findOne(id);
      await this.reporteRepository.remove(reporte);
      return { message: 'Reporte eliminado correctamente' };
    } catch (error) {
      if (error instanceof NotFoundException) {
        throw error;
      }
      console.error('Error en remove reporte:', error.message);
      throw new Error('Error al eliminar el reporte');
    }
  }

  // Obtener estadísticas
  async getEstadisticas() {
    try {
      const total = await this.reporteRepository.count();

      const hoy = new Date();
      const inicioMes = new Date(hoy.getFullYear(), hoy.getMonth(), 1);
      const finMes = new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0);

      const esteMes = await this.reporteRepository
        .createQueryBuilder('reporte')
        .where('reporte.fecha_reporte >= :inicio', { inicio: inicioMes })
        .andWhere('reporte.fecha_reporte <= :fin', { fin: finMes })
        .getCount();

      const ultimoReporte = await this.reporteRepository
        .createQueryBuilder('reporte')
        .orderBy('reporte.fecha_reporte', 'DESC')
        .limit(1)
        .getOne();

      return {
        total,
        este_mes: esteMes,
        ultimo_reporte: ultimoReporte,
      };
    } catch (error) {
      console.error('Error en getEstadisticas reportes:', error.message);
      return {
        total: 0,
        este_mes: 0,
        ultimo_reporte: null,
      };
    }
  }

  // Resumen analítico basado en el esquema monitoreo_analytics
  async getAnalyticsResumen() {
    try {
      // KPIs globales
      const kpis = await this.dataSource.query(
        `
        SELECT
          COUNT(*) AS total_operaciones,
          AVG(duracion_minutos) AS promedio_duracion_global,
          MIN(df.fecha) AS fecha_min,
          MAX(df.fecha) AS fecha_max
        FROM monitoreo_analytics.factoperacionmonitoreo f
        JOIN monitoreo_analytics.dimfecha df
          ON df.id_fecha = f.id_fecha_corte
        `,
      );

      // Duración promedio por medio de transporte y mes
      const duracionPorMedioMes = await this.dataSource.query(
        `
        SELECT
          df.anio,
          df.mes,
          fom.medio_transporte,
          AVG(fom.duracion_minutos) AS duracion_promedio_min
        FROM monitoreo_analytics.dimfecha df
        JOIN monitoreo_analytics.factoperacionmonitoreo fom
          ON df.id_fecha = fom.id_fecha_corte
        GROUP BY df.anio, df.mes, fom.medio_transporte
        ORDER BY df.anio, df.mes, fom.medio_transporte
        `,
      );

      // Incidencias de alta severidad por buque (top 10)
      const incidenciasAltaPorBuque = await this.dataSource.query(
        `
        SELECT
          db.nombre AS buque,
          SUM(fom.incidencias_alta_severidad) AS total_incidencias_alta
        FROM monitoreo_analytics.factoperacionmonitoreo fom
        JOIN monitoreo_analytics.dimbuque db
          ON db.id_buque = fom.id_buque
        GROUP BY db.nombre
        ORDER BY total_incidencias_alta DESC
        LIMIT 10
        `,
      );

      // Serie de tiempo por fecha y medio de transporte
      const serieTiempoPorMedio = await this.dataSource.query(
        `
        SELECT
          df.fecha,
          f.medio_transporte,
          AVG(f.duracion_minutos) AS duracion_promedio_min,
          SUM(f.incidencias_alta_severidad) AS incidencias_alta
        FROM monitoreo_analytics.factoperacionmonitoreo f
        JOIN monitoreo_analytics.dimfecha df
          ON df.id_fecha = f.id_fecha_corte
        GROUP BY df.fecha, f.medio_transporte
        ORDER BY df.fecha ASC, f.medio_transporte
        `,
      );

      return {
        kpis: kpis[0] || null,
        duracionPorMedioMes,
        incidenciasAltaPorBuque,
        serieTiempoPorMedio,
      };
    } catch (error: any) {
      console.error('Error en getAnalyticsResumen:', error.message || error);
      return {
        kpis: null,
        duracionPorMedioMes: [],
        incidenciasAltaPorBuque: [],
        serieTiempoPorMedio: [],
      };
    }
  }

  // Generar código único para el reporte
  private async generarCodigo(): Promise<string> {
    const fecha = new Date();
    const año = fecha.getFullYear().toString().slice(-2);
    const mes = (fecha.getMonth() + 1).toString().padStart(2, '0');

    // Obtener el último código del mes
    const ultimoReporte = await this.reporteRepository
      .createQueryBuilder('reporte')
      .where('reporte.codigo LIKE :patron', { patron: `RPT-${año}${mes}-%` })
      .orderBy('reporte.codigo', 'DESC')
      .getOne();

    let secuencial = 1;
    if (ultimoReporte) {
      const match = ultimoReporte.codigo.match(/-(\d+)$/);
      if (match) {
        secuencial = parseInt(match[1]) + 1;
      }
    }

    return `RPT-${año}${mes}-${secuencial.toString().padStart(4, '0')}`;
  }
}

